      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-invoice-tools\",\n  \"version\": \"0.1.1\",\n  \"description\": \"DSH 原生发票解析/报销单生成工具：读取工作区发票 PDF（XML 附件优先、文本层正则兜底），结构化 JSON + 金额勾稽校验，多张汇总生成报销单（Markdown / xlsx）。\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/types/index.d.ts\",\n  \"license\": \"MIT\",\n  \"engines\": {\n    \"node\": \">=22.18.0\"\n  },\n  \"keywords\": [\n    \"dsh\",\n    \"invoice\",\n    \"发票\",\n    \"报销\",\n    \"cordis\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.yml\"\n    },\n    \"compatibility\": {\n      \"node\": \">=22.18.0\",\n      \"dsh\": \">=0.1.0\"\n    },\n    \"permissions\": {\n      \"summary\": \"读取工作区发票 PDF（XML 附件优先、文本层正则兜底）→ 结构化 JSON + 金额勾稽校验 → 多张汇总生成报销单（Markdown/xlsx）。本机只读输入、写入输出文件；无查验接口网络调用。\",\n      \"commands\": [\n        \"node <pkg>/lib/*.js (pdf-extract in-process)\"\n      ],\n      \"writePaths\": [\n        \"<outDir>/*.md\",\n        \"<outDir>/*.xlsx\"\n      ],\n      \"externalServices\": [],\n      \"failureBoundaries\": [\n        \"解析失败结构化错误\",\n        \"FlateDecode 压缩路径\",\n        \"无上限缓存已有 TTL/上限\"\n      ],\n      \"lifecycleEvidence\": [\n        \"13 cases 12 pass + 1 skip (openpyxl 缺失)\",\n        \"test:offline 全绿\"\n      ]\n    }\n  },\n  \"dependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-tools\": \"0.1.1-rc.2\",\n    \"@deepseek-ai/dsh-fs\": \"0.1.1-rc.2\"\n  },\n  \"devDependencies\": {\n    \"@types/node\": \"^26.0.0\",\n    \"typescript\": \"^5.5.0\"\n  },\n  \"scripts\": {\n    \"build\": \"tsc -p tsconfig.json\",\n    \"typecheck\": \"tsc -p tsconfig.json --noEmit\",\n    \"test\": \"npm run build && node --test tests/\",\n    \"test:offline\": \"node --test tests/smoke.e2e.ts\",\n    \"prepublishOnly\": \"npm run build\"\n  },\n  \"files\": [\n    \"lib\",\n    \"src\",\n    \"cordis.yml\",\n    \"README.md\",\n    \"LICENSE\"\n  ],\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/988hj7tczd-oss/dsh-invoice-tools.git\"\n  }\n}\n"
