      "path": "src/index.ts",
      "content": "/**\n * src/index.ts — dsh-invoice-tools 装配入口。\n *\n * 注册两个 DSH 原生工具：\n *   - invoice_parse   ：发票解析（XML 优先 / 文本正则兜底 / 勾稽校验 / 核对表）\n *   - invoice_summary ：汇总 + 报销单生成（md / xlsx base64）\n *\n * 依赖注入（Cordis inject）：tools（工具注册表）、fs（工作区文件读写，遵守宿主沙箱/read 策略）。\n * 安全边界：不读取任何密钥/证书/账号配置；仅处理用户指定的发票文件（读取遵循宿主 fs 沙箱策略），\n * 输出写入工作区；不发起任何查验接口请求（查验为显式 opt-in，当前离线）。\n * 信任边界：文件经主机 ctx.fs 服务读写，fs 观察策略由宿主 fs 事件管道统一处理，本插件不做额外工作区包含校验。\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\n// 通过 dsh-fs 的类型增强注册 Context.fs（module augmentation，运行时零开销）\nimport type {} from '@deepseek-ai/dsh-fs'\nimport { invoiceParseTool } from './tools/invoice-parse.ts'\nimport { invoiceSummaryTool } from './tools/invoice-summary.ts'\n\nexport const name = 'invoice-tools'\n\n/** 硬依赖：tools 注册表与文件系统服务（apply 时已就绪）。 */\nexport const inject = ['tools', 'fs']\n\nexport function apply(ctx: Context) {\n  ctx.tools.register(invoiceParseTool(ctx))\n  ctx.tools.register(invoiceSummaryTool(ctx))\n  ctx.logger?.info('[invoice-tools] registered invoice_parse / invoice_summary')\n}"
