    {
      "path": "src/tools/invoice-parse.ts",
      "content": "/**\n * tools/invoice-parse.ts — invoice_parse 工具：单张/批量发票解析。\n *\n * 行为（对照功能规格第 1 条）：\n *  - path 为文件或目录（目录递归扫描，自动识别 pdf/jpg/png）；\n *  - 优先解析 PDF 内嵌结构化 XML（号码/代码/金额/税额/双方/日期），文本层正则兜底；\n *  - 输出结构化 JSON + 会话内\"抽取结果核对表\"（confidence：XML 直读=高/正则=中/缺失=低并列出）；\n *  - 勾稽校验：价税合计 = 金额 + 税额（容差 0.01），不符时在核对表标 ⚠；\n *  - 纯图片无 OCR / 加密 PDF 返回明确\"跳过原因\"，不中断批量。\n */\n\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport type { Context } from '@deepseek-ai/cordis'\nimport { extractPdf, detectFileKind } from '../pdf-extract.ts'\nimport {\n  type InvoiceData,\n  parseInvoiceFromTextLines,\n  parseInvoiceFromXml,\n  validateInvoice,\n} from '../invoice-model.ts'\n\n/** 解析缓存：invoice_summary 缺省 files 时复用上次 parse 结果。\n *  key 为 `${scope}:${absPath}`，scope 为会话 id（工具执行上下文的 agent.id）——按会话隔离；\n *  无法取得会话上下文时回退 'global'（进程级缓存，README「安全与隐私」已如实说明）。 */\nexport const parseCache = new Map<string, InvoiceData>()\n\n/** 缓存作用域：有会话 id 用会话 id；否则回退 'global'（进程级，见 README）。 */\nexport function cacheScope(sessionId: string | undefined | null): string {\n  return sessionId && sessionId.length > 0 ? sessionId : 'global'\n}\n\n/** 单文件读取上限（PDF 通常 < 8MB，给 16MB 余量）。 */\nconst MAX_BYTES = 16 * 1024 * 1024\n\nexport interface SkippedFile {\n  path: string\n  file: string\n  reason: 'password-protected' | 'image-without-ocr' | 'unsupported-file-type' | 'unparsable' | 'empty-pdf'\n  detail?: string\n}\n\nexport interface InvoiceParseResult {\n  inputCount: number\n  parsed: (InvoiceData & { path: string })[]\n  skipped: SkippedFile[]\n  summary: {\n    parsedCount: number\n    skippedCount: number\n    amount: number\n    tax: number\n    total: number\n    checksFailed: number\n  }\n}\n\nconst SUPPORTED_EXT = new Set(['.pdf', '.jpg', '.jpeg', '.png'])\n\nfunction hasSupportedExt(name: string): boolean {\n  const lower = name.toLowerCase()\n  for (const ext of SUPPORTED_EXT) if (lower.endsWith(ext)) return true\n  return false\n}\n\n/** 递归收集发票文件（目录深度上限 3）。 */\nasync function collectFiles(ctx: Context, target: Awaited<ReturnType<Context['fs']['resolve']>>, signal: AbortSignal | undefined, depth: number, acc: { name: string; target: Awaited<ReturnType<Context['fs']['resolve']>> }[]): Promise<void> {\n  if (depth > 3) return\n  const info = await ctx.fs.stat(target, signal)\n  if (!info) return\n  if (info.type === 'file') {\n    const abs = ctx.fs.processPath(target)\n    if (hasSupportedExt(abs)) acc.push({ name: abs.split('/').pop() ?? abs, target })\n    return\n  }\n  if (info.type === 'directory') {\n    const entries = await ctx.fs.listDir(target, signal)\n    for (const entry of entries) {\n      if (entry.type === 'file' && hasSupportedExt(entry.name)) acc.push({ name: entry.name, target: entry.target })\n      else if (entry.type === 'directory') await collectFiles(ctx, entry.target, signal, depth + 1, acc)\n    }\n  }\n}\n\n/** 解析单文件字节为 InvoiceData 或跳过记录。 */\nfunction parseOne(ctx: Context, path: string, name: string, bytes: Uint8Array): { invoice?: InvoiceData; skipped?: SkippedFile } {\n  const kind = detectFileKind(bytes, name)\n  if (kind === 'png' || kind === 'jpg') {\n    return { skipped: { path, file: name, reason: 'image-without-ocr', detail: '纯图片无 OCR：首版不支持扫描件识别，见 README（后续可对接社区 vision 插件）' } }\n  }\n  if (kind === 'other') {\n    return { skipped: { path, file: name, reason: 'unsupported-file-type', detail: `不支持的文件类型（检测到非 PDF/PNG/JPEG 内容，扩展名 ${name.split('.').pop() ?? ''}）` } }\n  }\n  // PDF\n  const extraction = extractPdf(bytes)\n  if (extraction.encrypted) {\n    return { skipped: { path, file: name, reason: 'password-protected', detail: 'PDF 声明 /Encrypt（密码保护或加密），无法解析' } }\n  }\n  const xmlText = extraction.embeddedXml.length > 0 ? extraction.embeddedXml.join('\\n') : ''\n  if (xmlText.trim().length > 0) {\n    const invoice = parseInvoiceFromXml(xmlText, name, extraction.text)\n    if (invoice.invoiceNumber === '' && invoice.amount === 0 && invoice.total === 0) {\n      return { skipped: { path, file: name, reason: 'unparsable', detail: '找到 XML 附件但未抽取到有效字段（附件 Schema 不在白名单内）' } }\n    }\n    return { invoice }\n  }\n  if (extraction.text.trim().length > 0) {\n    return { invoice: parseInvoiceFromTextLines(extraction.text, name) }\n  }\n  return { skipped: { path, file: name, reason: 'empty-pdf', detail: 'PDF 无文本层且无 XML 附件（扫描件需 OCR）' } }\n}\n\n/** 执行解析编排（也被工具 execute 与测试复用其纯逻辑核心）。 */\nexport async function runInvoiceParse(\n  ctx: Context,\n  args: { path: string },\n  signal?: AbortSignal,\n  sessionId?: string,\n): Promise<InvoiceParseResult> {\n  const target = await ctx.fs.resolve(args.path, { signal })\n  const info = await ctx.fs.stat(target, signal)\n  if (!info) throw new Error(`路径不存在: ${args.path}`)\n\n  const files: { name: string; target: Awaited<ReturnType<Context['fs']['resolve']>> }[] = []\n  const pathInfo = ctx.fs.processPath(target)\n  if (info.type === 'file') {\n    if (!hasSupportedExt(pathInfo)) {\n      throw new Error(`不是支持的发票文件（支持 pdf/jpg/png）: ${args.path}`)\n    }\n    files.push({ name: pathInfo.split('/').pop() ?? pathInfo, target })\n  } else {\n    await collectFiles(ctx, target, signal, 0, files)\n  }\n\n  const parsed: (InvoiceData & { path: string })[] = []\n  const skipped: SkippedFile[] = []\n  let checksFailed = 0\n  const scope = cacheScope(sessionId)\n\n  for (const file of files) {\n    const absPath = ctx.fs.processPath(file.target)\n    let bytes: Uint8Array\n    try {\n      bytes = await ctx.fs.readBytes(file.target, signal, MAX_BYTES)\n    } catch (error) {\n      skipped.push({ path: absPath, file: file.name, reason: 'unparsable', detail: `读取失败: ${error instanceof Error ? error.message : String(error)}` })\n      continue\n    }\n    const r = parseOne(ctx, absPath, file.name, bytes)\n    if (r.skipped) {\n      skipped.push(r.skipped)\n      continue\n    }\n    const invoice = r.invoice!\n    invoice.checks = validateInvoice(invoice)\n    if (!invoice.checks.every((c) => c.ok)) checksFailed += 1\n    parseCache.set(`${scope}:${absPath}`, invoice)\n    parsed.push({ ...invoice, path: absPath })\n  }\n\n  const amount = parsed.reduce((acc, p) => acc + p.amount, 0)\n  const tax = parsed.reduce((acc, p) => acc + p.tax, 0)\n  const total = parsed.reduce((acc, p) => acc + p.total, 0)\n\n  return {\n    inputCount: files.length,\n    parsed,\n    skipped,\n    summary: {\n      parsedCount: parsed.length,\n      skippedCount: skipped.length,\n      amount,\n      tax,\n      total,\n      checksFailed,\n    },\n  }\n}\n\n/** 核对表渲染（会话内表格）。 */\nexport function renderParseResult(result: InvoiceParseResult): string {\n  const lines: string[] = []\n  lines.push('## 发票解析结果核对表')\n  lines.push('')\n  lines.push(`共扫描 **${result.inputCount}** 个文件：解析成功 **${result.summary.parsedCount}**，跳过 **${result.summary.skippedCount}**。`)\n  lines.push('')\n  if (result.parsed.length > 0) {\n    lines.push('| 源文件 | 发票号码 | 发票代码 | 开票日期 | 金额 | 税额 | 价税合计 | 来源 | 置信度 | 勾稽 | 缺失字段 |')\n    lines.push('| --- | --- | --- | --- | ---: | ---: | ---: | --- | --- | --- | --- |')\n    for (const inv of result.parsed) {\n      const missing = inv.source.missing.length > 0 ? inv.source.missing.join('、') : '—'\n      const recon = inv.checks.find((c) => c.label.startsWith('勾稽'))\n      const reconCell = recon === undefined ? '—' : recon.ok ? '✓' : `⚠ ${recon.detail}`\n      const confLabel = inv.source.confidence === 'high' ? '高(XML)' : inv.source.confidence === 'medium' ? '中(正则)' : `低(缺:${missing})`\n      const methodLabel = inv.source.method === 'xml' ? 'XML' : inv.source.method === 'mixed' ? 'XML+文本' : '文本正则'\n      lines.push(\n        `| ${inv.source.file} | ${inv.invoiceNumber} | ${inv.invoiceCode || '—'} | ${inv.issueDate || '—'} | ${inv.amount.toFixed(2)} | ${inv.tax.toFixed(2)} | ${inv.total.toFixed(2)} | ${methodLabel} | ${confLabel} | ${reconCell} | ${missing} |`,\n      )\n    }\n    lines.push('')\n    lines.push(`本批合计：金额 **¥${result.summary.amount.toFixed(2)}**，税额 **¥${result.summary.tax.toFixed(2)}**，价税合计 **¥${result.summary.total.toFixed(2)}**（勾稽失败 ${result.summary.checksFailed} 张，见上表 ⚠）。`)\n  }\n  if (result.skipped.length > 0) {\n    lines.push('')\n    lines.push('### 跳过清单')\n    lines.push('')\n    lines.push('| 源文件 | 跳过原因 | 说明 |')\n    lines.push('| --- | --- | --- |')\n    for (const s of result.skipped) lines.push(`| ${s.file} | ${s.reason} | ${s.detail ?? ''} |`)\n  }\n  return lines.join('\\n')\n}\n\n/** 定义 invoice_parse 工具。 */\nexport function invoiceParseTool(ctx: Context) {\n  return defineTool({\n    name: 'invoice_parse',\n    description:\n      '解析工作区内的发票文件（PDF 或目录，自动识别 pdf/jpg/png）：优先读取 PDF 内嵌结构化 XML（发票号码/代码、金额、税额、价税合计、购买方、销售方、开票日期），无 XML 时用文本层正则抽取；输出结构化 JSON 并渲染\"抽取结果核对表\"（含置信度与金额勾稽校验）。纯图片/加密 PDF 返回跳过原因，不中断批量。发票数据仅本地流转，不发起任何查验请求。',\n    parameters: {\n      path: {\n        type: 'string',\n        required: true,\n        description: '发票文件路径或目录（目录将递归扫描 pdf/jpg/png）',\n      },\n    },\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        properties: {\n          inputCount: { type: 'integer' },\n          parsed: { type: 'array', items: { type: 'json' } },\n          skipped: { type: 'array', items: { type: 'json' } },\n          summary: { type: 'object', additionalProperties: true, properties: {} },\n        },\n      },\n      render: (_args, value: any) => [{ type: 'text', text: renderParseResult(value as InvoiceParseResult) }],\n      presentationMeta: (_args, value: any) => ({\n        kind: 'invoice-parse',\n        title: `解析 ${value.summary.parsedCount} 张发票${value.summary.checksFailed > 0 ? `（⚠${value.summary.checksFailed} 张勾稽失败）` : ''}`,\n        parsedCount: value.summary.parsedCount,\n        skippedCount: value.summary.skippedCount,\n        total: value.summary.total,\n        checksFailed: value.summary.checksFailed,\n      }),\n    },\n    async execute(args, exec) {\n      // schema 推断出的输出类型与业务类型形状不同，桥接返回（运行时数据本身就是 JSON 可序列化结构）\n      // 会话维度：exec.agent.id 即会话 id（由代理循环设置）；拿不到时回退 global（进程级缓存）\n      const sessionId = (exec as unknown as { agent?: { id?: string } } | undefined)?.agent?.id\n      return runInvoiceParse(ctx, args, exec?.signal, sessionId) as any\n    },\n  })\n}"
    },
    {
      "path": "src/tools/invoice-summary.ts",
      "content": "/**\n * tools/invoice-summary.ts — invoice_summary 工具：汇总 + 报销单生成。\n *\n * 行为（对照功能规格第 2 条）：\n *  - files 缺省时复用 invoice_parse 的解析缓存（key 含会话作用域，见 invoice-parse.ts）；\n *  - 汇总结算（合计/税额/按类别）、重复票检测（同票号+同金额）；\n *  - 生成报销单文件到工作区（Markdown 直写；xlsx 因 DSH 工作区为文本信道，\n *    以 base64 文本 (.b64) 落盘，README 提供解码命令）+ 会话内汇总表格；\n *  - 安全：写目标前先 stat/read（\"已存在目标先 read\"），再以版本守卫写入。\n */\n\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport type { Context } from '@deepseek-ai/cordis'\nimport { type InvoiceData } from '../invoice-model.ts'\nimport { cacheScope, parseCache } from './invoice-parse.ts'\nimport { reimbursementBaseName, renderMarkdown, renderXlsx, summarizeInvoices, type InvoiceSummary } from '../summary.ts'\n\nexport interface InvoiceSummaryResult {\n  invoicesCount: number\n  summary: InvoiceSummary\n  files: { path: string; kind: 'md' | 'xlsx' | 'both'; operation: 'create' | 'update'; size: number }[]\n  xlsxBase64?: string\n  note?: string\n}\n\n/** 金额四舍五入到分（仅用于展示）。 */\nfunction round2(n: number): number {\n  return Math.round(n * 100) / 100\n}\n\n/** 写文本文件：已存在目标先 read，再带版本守卫写入；不存在则 createIfAbsent。 */\nasync function writeGuardedText(\n  ctx: Context,\n  relativePath: string,\n  content: string,\n  signal?: AbortSignal,\n): Promise<{ operation: 'create' | 'update'; absPath: string }> {\n  const target = await ctx.fs.resolve(relativePath, { signal })\n  const info = await ctx.fs.stat(target, signal)\n  if (info) {\n    // 已存在目标先 read（遵循 read 策略），再以版本守卫覆盖\n    await ctx.fs.readText(target, signal)\n    await ctx.fs.writeText(target, content, { kind: 'replaceIfVersion', version: info.version }, signal)\n    return { operation: 'update', absPath: ctx.fs.processPath(target) }\n  }\n  await ctx.fs.writeText(target, content, { kind: 'createIfAbsent' }, signal)\n  return { operation: 'create', absPath: ctx.fs.processPath(target) }\n}\n\n/** 执行汇总 + 报销单生成。 */\nexport async function runInvoiceSummary(\n  ctx: Context,\n  args: { files?: string[]; out?: 'md' | 'xlsx' | 'both'; categories?: Record<string, string> },\n  signal?: AbortSignal,\n  sessionId?: string,\n): Promise<InvoiceSummaryResult> {\n  // 只可见当前会话作用域的缓存条目（跨会话隔离；无会话 id 时为 global 进程级）\n  const scope = cacheScope(sessionId)\n  const scopePrefix = `${scope}:`\n  let invoices: InvoiceData[]\n  if (args.files !== undefined && args.files.length > 0) {\n    const matched: InvoiceData[] = []\n    const missing: string[] = []\n    for (const f of args.files) {\n      const hit = [...parseCache.entries()].find(([key, inv]) => {\n        if (!key.startsWith(scopePrefix)) return false\n        const absPath = key.slice(scopePrefix.length)\n        return absPath === f || absPath.endsWith(`/${f}`) || inv.source.file === f\n      })\n      if (hit) matched.push(hit[1])\n      else missing.push(f)\n    }\n    if (missing.length > 0) {\n      throw new Error(`以下文件尚未解析，请先运行 invoice_parse：${missing.join('、')}`)\n    }\n    invoices = matched\n  } else {\n    invoices = [...parseCache.entries()].filter(([key]) => key.startsWith(scopePrefix)).map(([, inv]) => inv)\n  }\n  if (invoices.length === 0) {\n    throw new Error('当前会话没有可汇总的发票：请先运行 invoice_parse，或通过 files 参数指定已解析文件')\n  }\n\n  // 类别覆盖：按发票号码或源文件名匹配\n  if (args.categories) {\n    for (const inv of invoices) {\n      const byNo = args.categories[inv.invoiceNumber]\n      const byFile = args.categories[inv.source.file]\n      if (byNo !== undefined) inv.category = byNo\n      else if (byFile !== undefined) inv.category = byFile\n    }\n  }\n\n  const summary = summarizeInvoices(invoices)\n  const out = args.out ?? 'md'\n  const base = reimbursementBaseName()\n  const files: InvoiceSummaryResult['files'] = []\n  let xlsxBase64: string | undefined\n\n  if (out === 'md' || out === 'both') {\n    const md = renderMarkdown(invoices, summary, { generatedAt: new Date().toISOString() })\n    const res = await writeGuardedText(ctx, `${base}.md`, md, signal)\n    files.push({ path: res.absPath, kind: 'md', operation: res.operation, size: Buffer.byteLength(md, 'utf8') })\n  }\n  if (out === 'xlsx' || out === 'both') {\n    const xlsxBytes = renderXlsx(invoices, summary)\n    xlsxBase64 = Buffer.from(xlsxBytes).toString('base64')\n    // DSH fs 服务仅提供 UTF-8 文本信道，xlsx 以 base64 文本落盘（README 提供解码命令）\n    const b64Path = `${base}.xlsx.b64`\n    const res = await writeGuardedText(ctx, b64Path, xlsxBase64, signal)\n    files.push({ path: res.absPath, kind: 'xlsx', operation: res.operation, size: Buffer.byteLength(xlsxBase64, 'utf8') })\n  }\n\n  return {\n    invoicesCount: invoices.length,\n    summary,\n    files,\n    xlsxBase64,\n    note:\n      '隐私说明：发票数据仅在本机流转，不发起任何查验接口请求（查验为显式 opt-in，默认关闭）。解析缓存按会话隔离——工具无法取得会话上下文时回退为进程级缓存（见 README）。xlsx 以 base64 文本落盘，解码命令见 README。',\n  }\n}\n\n/** 汇总结果会话内渲染。 */\nexport function renderSummaryResult(result: InvoiceSummaryResult): string {\n  const lines: string[] = []\n  const t = result.summary.totals\n  lines.push('## 报销单汇总')\n  lines.push('')\n  lines.push(`参与汇总 **${result.invoicesCount}** 张发票：`)\n  lines.push('')\n  lines.push('| 张数 | 金额合计 | 税额合计 | 价税合计 |')\n  lines.push('| ---: | ---: | ---: | ---: |')\n  lines.push(`| ${t.count} | ¥${t.amount.toFixed(2)} | ¥${t.tax.toFixed(2)} | ¥${t.total.toFixed(2)} |`)\n\n  if (result.summary.byCategory.length > 1 || (result.summary.byCategory[0] && result.summary.byCategory[0].category !== '未分类')) {\n    lines.push('')\n    lines.push('### 按类别小计')\n    lines.push('')\n    lines.push('| 类别 | 张数 | 金额 | 税额 | 价税合计 |')\n    lines.push('| --- | ---: | ---: | ---: | ---: |')\n    for (const c of result.summary.byCategory) {\n      lines.push(`| ${c.category} | ${c.count} | ¥${c.amount.toFixed(2)} | ¥${c.tax.toFixed(2)} | ¥${c.total.toFixed(2)} |`)\n    }\n  }\n\n  if (result.summary.duplicates.length > 0) {\n    lines.push('')\n    lines.push('### ⚠ 重复票检测')\n    lines.push('')\n    lines.push('| 票号 | 金额 | 文件 | 建议剔除 |')\n    lines.push('| --- | ---: | --- | --- |')\n    for (const d of result.summary.duplicates) {\n      lines.push(`| ${d.invoiceNumber} | ${d.amount.toFixed(2)} | ${d.files.join('、')} | ${d.flagged.join('、')} |`)\n    }\n  }\n\n  lines.push('')\n  lines.push('### 已生成文件')\n  lines.push('')\n  for (const f of result.files) {\n    lines.push(`- \\`${f.path}\\`（${f.kind === 'md' ? 'Markdown 报销单' : 'xlsx base64'}，${f.operation === 'create' ? '新建' : '已存在并更新'}，${(f.size / 1024).toFixed(1)} KB）`)\n  }\n  if (result.xlsxBase64) {\n    lines.push('')\n    lines.push('xlsx 内容以 base64 文本落盘（DSH 工作区为文本信道）。解码命令：`base64 -d 报销单-<日期>.xlsx.b64 > 报销单-<日期>.xlsx`')\n  }\n  if (result.note) lines.push('')\n  if (result.note) lines.push(`> ${result.note}`)\n  return lines.join('\\n')\n}\n\n/** 定义 invoice_summary 工具。 */\nexport function invoiceSummaryTool(ctx: Context) {\n  return defineTool({\n    name: 'invoice_summary',\n    description:\n      '汇总已解析发票并生成报销单：files 缺省时复用 invoice_parse 的解析缓存（按会话隔离，无会话上下文时为进程级）；汇总结算（合计/税额/按类别小计）、重复票检测（同票号+同金额）；生成报销单文件到工作区（out=md/xlsx/both，默认 md）。文件经宿主 ctx.fs 服务读写（已存在目标先 read 再版本守卫写入；观察策略由宿主 fs 事件管道统一处理）。',\n    parameters: {\n      files: {\n        type: 'array',\n        items: { type: 'string' },\n        description: '参与汇总的发票文件（必需已通过 invoice_parse 解析；缺省使用上次 parse 的全部结果）',\n      },\n      out: {\n        type: 'string',\n        enum: ['md', 'xlsx', 'both'],\n        description: '输出格式：md（默认）| xlsx（base64 文本落盘）| both',\n      },\n      categories: {\n        type: 'json',\n        description: '费用类别映射（键为发票号码或源文件名，值为类别名），用于按类别小计',\n      },\n    },\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        properties: {\n          invoicesCount: { type: 'integer' },\n          summary: { type: 'object', additionalProperties: true, properties: {} },\n          files: { type: 'array', items: { type: 'json' } },\n          xlsxBase64: { type: 'string' },\n          note: { type: 'string' },\n        },\n      },\n      render: (_args, value: any) => [{ type: 'text', text: renderSummaryResult(value as InvoiceSummaryResult) }],\n      presentationMeta: (_args, value: any) => ({\n        kind: 'invoice-summary',\n        title: `报销单汇总 ${value.invoicesCount} 张 · 价税合计 ¥${round2(value.summary.totals.total).toFixed(2)}`,\n        invoicesCount: value.invoicesCount,\n        total: round2(value.summary.totals.total),\n        duplicateCount: value.summary.duplicates.length,\n        files: value.files.map((f: { path: string }) => f.path),\n      }),\n    },\n    async execute(args, exec) {\n      const sessionId = (exec as unknown as { agent?: { id?: string } } | undefined)?.agent?.id\n      const categories = args.categories as Record<string, string> | undefined\n      return runInvoiceSummary(ctx, { files: args.files, out: args.out, categories }, exec?.signal, sessionId) as any\n    },\n  })\n}"
    },
    {
      "path": "src/invoice-model.ts",
      "content": "/**\n * invoice-model.ts — 发票字段模型、XML/文本正则抽取、金额勾稽校验（纯逻辑，零依赖）。\n *\n * 该模块按国内增值税电子发票（数电票/全电发票）的实际字段规范自写：\n *  - XML 附件（offlineinvoice / Envelope）优先：通过候选标签白名单（中英双语）抽取字段；\n *  - 文本层兜底：标签定位 + 正则（票号 \\d{8,20}、金额/税额/价税合计、日期、双方名称）；\n *  - 勾稽校验：价税合计 = 金额 + 税额（容差 0.01）；\n *  - confidence：XML 直读=高，正则=中，关键字段缺失=低并列出缺失清单。\n *\n * 本模块不 import 任何外部运行时依赖（仅类型安全），可被离线测试直接执行。\n */\n\n/** 购买方 / 销售方信息。 */\nexport interface InvoiceParty {\n  /** 名称（默认空串表示字段缺失）。 */\n  name: string\n  /** 税号。 */\n  taxId: string\n}\n\n/** 一条校验结果（勾稽、字段合法性等）。 */\nexport interface InvoiceCheck {\n  label: string\n  ok: boolean\n  detail?: string\n}\n\n/** 抽取来源。 */\nexport type InvoiceSourceMethod = 'xml' | 'regex' | 'mixed'\n/** 置信度：XML 直读=high，正则=medium，关键字段缺失=low。 */\nexport type InvoiceConfidence = 'high' | 'medium' | 'low'\n\n/** 结构化发票数据（DSH 会话内流转的唯一业务对象）。 */\nexport interface InvoiceData {\n  /** 发票代码（全电发票可为空）。 */\n  invoiceCode: string\n  /** 发票号码（至少 8 位数字）。 */\n  invoiceNumber: string\n  /** 金额（不含税）。 */\n  amount: number\n  /** 税额。 */\n  tax: number\n  /** 价税合计。 */\n  total: number\n  /** 开票日期 YYYY-MM-DD。 */\n  issueDate: string\n  buyer: InvoiceParty\n  seller: InvoiceParty\n  /** 查验平台网址（可选，默认不发起任何查验请求）。 */\n  verifyUrl?: string\n  /** 费用类别（汇总时按类别小计；未指定为 undefined，归入\"未分类\"）。 */\n  category?: string\n  /** 校验结果列表（勾稽等）。 */\n  checks: InvoiceCheck[]\n  /** 抽取来源元信息。 */\n  source: {\n    /** 源文件名（basename）。 */\n    file: string\n    method: InvoiceSourceMethod\n    confidence: InvoiceConfidence\n    /** 缺失字段清单（关键字段缺失会拉低 confidence）。 */\n    missing: string[]\n    /** 文本正则路径命中的规则名（仅用于诊断）。 */\n    matchedRules?: string[]\n  }\n}\n\n/** 解析出的原始字段（值为抽取出的字符串，未做数值/日期归一）。 */\nexport interface RawInvoiceFields {\n  invoiceCode?: string\n  invoiceNumber?: string\n  amount?: string\n  tax?: string\n  total?: string\n  issueDate?: string\n  buyerName?: string\n  buyerTaxId?: string\n  sellerName?: string\n  sellerTaxId?: string\n  verifyUrl?: string\n}\n\n/** 关键字段：缺失会拉低 confidence / 影响勾稽与汇总。 */\nexport const KEY_FIELDS = ['invoiceNumber', 'amount', 'tax', 'total'] as const\n\n/** 勾稽容差（元）。 */\nexport const TOTAL_TOLERANCE = 0.01\n\n/** 数值型候选标签（XML 附件标签名，中英双语，按国内数电票常见 Schema 收集）。 */\nconst NUMERIC_TAG_CANDIDATES: Record<'invoiceCode' | 'invoiceNumber' | 'amount' | 'tax' | 'total', string[]> = {\n  invoiceCode: ['发票代码', 'InvoiceCode', 'FPDM'],\n  invoiceNumber: ['发票号码', 'InvoiceNo', 'InvoiceNumber', 'FPHM'],\n  amount: ['金额', 'TaxExclusiveAmount', 'AmountWithoutTax', 'PretaxAmount', 'KCE', 'Amount'],\n  tax: ['税额', 'TaxAmount', 'TotalTaxAmount', 'SE'],\n  total: ['价税合计', 'TaxInclusiveAmount', 'AmountWithTax', 'InvoiceAmount', 'FPHJJE', 'Total'],\n}\n\n/** 文本型候选标签。 */\nconst TEXT_TAG_CANDIDATES: Record<'issueDate' | 'buyerName' | 'buyerTaxId' | 'sellerName' | 'sellerTaxId' | 'verifyUrl', string[]> = {\n  issueDate: ['开票日期', 'IssueDate', 'BillingDate', 'KPRQ', 'InvoiceDate'],\n  buyerName: ['购买方名称', 'BuyerName', 'PurchaserName', 'GMFMC'],\n  buyerTaxId: ['购买方纳税人识别号', 'BuyerTaxId', 'PurchaserTaxId', 'GMFSBH'],\n  sellerName: ['销售方名称', 'SellerName', 'SupplierName', 'XSFMC'],\n  sellerTaxId: ['销售方纳税人识别号', 'SellerTaxId', 'SupplierTaxId', 'XSFSBH'],\n  verifyUrl: ['查验平台网址', 'VerifyUrl', 'CheckUrl', 'CZPT'],\n}\n\n/**\n * 金额字符串归一：去掉 ¥/￥/逗号/空白，支持可选负号（红字发票），\n * 返回有限数值；无法解析返回 null。\n */\nexport function normalizeMoney(raw: string): number | null {\n  const cleaned = raw.replace(/[¥￥,，\\s]/g, '')\n  if (!/^-?\\d+(\\.\\d+)?$/.test(cleaned)) return null\n  const n = Number(cleaned)\n  return Number.isFinite(n) ? n : null\n}\n\n/**\n * 日期字符串归一为 YYYY-MM-DD。接受 20240105 / 2024-01-05 / 2024年01月05日 等。\n * 解析失败返回 null。\n */\nexport function normalizeDate(raw: string): string | null {\n  const m = /(\\d{4})[-年.\\/]?(\\d{1,2})[-月.\\/]?(\\d{1,2})日?/.exec(raw.trim())\n  if (!m) return null\n  const y = m[1]\n  const mo = String(Number(m[2])).padStart(2, '0')\n  const d = String(Number(m[3])).padStart(2, '0')\n  if (Number(mo) < 1 || Number(mo) > 12 || Number(d) < 1 || Number(d) > 31) return null\n  return `${y}-${mo}-${d}`\n}\n\n/**\n * 收集 XML 中所有\"叶子\"双标签 <tag>value</tag>（value 内不含子标签）：\n * 以栈配对开始/结束标签，从最内层向外记录叶子值，保序、去重（同名标签取第一个）。\n * 不依赖任何 DOM 解析器，兼容中英文标签名。\n */\nexport function collectXmlTags(xml: string): Map<string, string> {\n  const map = new Map<string, string>()\n  const tagRe = /<\\/?([A-Za-z_\\u4e00-\\u9fa5A-Z][A-Za-z0-9_\\u4e00-\\u9fa5.\\-]*)(?:\\s[^>]*)?>/g\n  const stack: { tag: string; contentStart: number }[] = []\n  let m: RegExpExecArray | null\n  while ((m = tagRe.exec(xml)) !== null) {\n    const token = m[0]\n    const tag = m[1]\n    if (token.startsWith('</')) {\n      // 找最近未闭合的同名标签（最内层优先）\n      let found = -1\n      for (let i = stack.length - 1; i >= 0; i--) {\n        if (stack[i].tag === tag) {\n          found = i\n          break\n        }\n      }\n      if (found >= 0) {\n        const open = stack[found]\n        stack.length = found\n        const content = xml.slice(open.contentStart, m.index)\n        // 叶子：内容不含子标签\n        if (!content.includes('<') && content.trim().length > 0 && !map.has(tag)) {\n          map.set(tag, content.trim())\n        }\n      }\n    } else if (!token.endsWith('/>')) {\n      stack.push({ tag, contentStart: m.index + token.length })\n    }\n  }\n  return map\n}\n\n/** 依候选标签白名单从 XML 标签表抽取原始字段。 */\nexport function fieldsFromXmlTags(tags: Map<string, string>): RawInvoiceFields {\n  const fields: RawInvoiceFields = {}\n  for (const [field, candidates] of Object.entries(NUMERIC_TAG_CANDIDATES) as [keyof RawInvoiceFields, string[]][]) {\n    for (const tag of candidates) {\n      const value = tags.get(tag)\n      if (value !== undefined && normalizeMoney(value) !== null) {\n        fields[field] = value\n        break\n      }\n    }\n  }\n  for (const [field, candidates] of Object.entries(TEXT_TAG_CANDIDATES)) {\n    for (const tag of candidates) {\n      const value = tags.get(tag)\n      if (value !== undefined && value.length > 0) {\n        fields[field as keyof RawInvoiceFields] = value\n        break\n      }\n    }\n  }\n  return fields\n}\n\n// ---------------------------------------------------------------------------\n// 文本层正则规则（无 XML 时的兜底路径）\n// ---------------------------------------------------------------------------\n\n/** 正则抽取结果：字段 + 命中规则名。 */\nexport interface TextParseResult {\n  fields: RawInvoiceFields\n  matchedRules: string[]\n}\n\n/**\n * 从 PDF 文本层抽取发票字段。规则按标签定位 + 正则：\n *  - 票号 \\d{8,20}（发票号码 / 发票代码标签后）；\n *  - 金额/税额/价税合计：标签后（大写…小写）括号段跳过，取小写数值；\n *  - 开票日期、双方名称、纳税人识别号、查验平台网址。\n */\nexport function parseInvoiceFromText(text: string): TextParseResult {\n  const fields: RawInvoiceFields = {}\n  const matchedRules: string[] = []\n  // 压缩连续空白，避免\"标签  值\"匹配失败；t1 再把换行抹平为空格，\n  // 使【金额（大写）…\\n（小写）¥x】之类跨行写法也能被金额规则匹配到。\n  const t = text.replace(/[ \\t\\u00a0]+/g, ' ')\n  const t1 = t.replace(/\\n/g, ' ')\n\n  // 发票代码 / 发票号码：\\d{8,20}，先号码后代码\n  let m = /发票号码[：: ]*([0-9]{8,20})/.exec(t)\n  if (m) {\n    fields.invoiceNumber = m[1]\n    matchedRules.push('invoiceNumber')\n  }\n  // 兜底：无\"发票号码\"标签时取文本中全部 8-20 位数字里最长者（全电票号 20 位，\n  // 通常长于发票代码；无发票语义的普通文档会因其他关键字段缺失而降 confidence）。\n  if (!fields.invoiceNumber) {\n    const nums = [...t.matchAll(/[0-9]{8,20}/g)].map((x) => x[0])\n    const best = nums.sort((a, b) => b.length - a.length)[0]\n    if (best !== undefined && t.includes('发票')) {\n      fields.invoiceNumber = best\n      matchedRules.push('invoiceNumber-fallback')\n    }\n  }\n  m = /发票代码[：: ]*([0-9]{6,20})/.exec(t)\n  if (m) {\n    fields.invoiceCode = m[1]\n    matchedRules.push('invoiceCode')\n  }\n\n  // 日期：2024年01月05日 / 2024-01-05\n  m = /开票日期[：: ]*(\\d{4})[年\\-.\\/](\\d{1,2})[月\\-.\\/](\\d{1,2})日?/.exec(t)\n  if (m) {\n    const normalized = normalizeDate(`${m[1]}-${m[2]}-${m[3]}`)\n    if (normalized) {\n      fields.issueDate = normalized\n      matchedRules.push('issueDate')\n    }\n  }\n\n  // 金额 / 税额 / 价税合计：标签后允许 ≤2 个（大写）…（小写）括号段（段间可含大写金额\n  // 等非数字文本），再取数值。forbidBefore 为可选的\"禁止前缀\"字符类：'金额'/'税额' 是\n  // '合计金额'/'合计税额' 等标签的后缀，直接以标签子串匹配会命中合计行——真实版式里\n  // \"合计金额…（小写）¥价税合计数值\" 会把价税合计误绑成金额。故金额/税额排除\n  // '合/计/价/税' 前缀（合计金额、价税合计金额），价税合计以精确标签单独处理。\n  const moneyRule = (label: string, forbidBefore?: string): string | null => {\n    const head = forbidBefore ? `(?<![${forbidBefore}])` : ''\n    const re = new RegExp(\n      `${head}${label}(?:[（(][^（）()]*[）)][^（）()¥￥0-9]{0,60}){0,2}[：: ]*[¥￥]?\\\\s*(-?[0-9][0-9,.]*)`,\n    )\n    const mm = re.exec(t1)\n    return mm ? mm[1] : null\n  }\n  // 金额：优先精确标签\"金额（不含税）\"；兜底\"金额\"并排除 '合计/价税' 前缀碰撞\n  const amountRaw = moneyRule('金额（不含税）', '价计税') ?? moneyRule('金额', '价计税')\n  // 税额：排除 '合计税额' 前缀碰撞\n  const taxRaw = moneyRule('税额', '计')\n  // 价税合计：精确标签，独立取数（不与 金额 规则竞争）\n  const totalRaw = moneyRule('价税合计')\n  if (amountRaw !== null) {\n    fields.amount = amountRaw\n    matchedRules.push('amount')\n  }\n  if (taxRaw !== null) {\n    fields.tax = taxRaw\n    matchedRules.push('tax')\n  }\n  if (totalRaw !== null) {\n    fields.total = totalRaw\n    matchedRules.push('total')\n  }\n\n  // 购买方 / 销售方 名称\n  m = /购买方名称[：: ]*([^\\n]{2,80})/.exec(t)\n  if (m) {\n    fields.buyerName = m[1].trim()\n    matchedRules.push('buyerName')\n  }\n  m = /销售方名称[：: ]*([^\\n]{2,80})/.exec(t)\n  if (m) {\n    fields.sellerName = m[1].trim()\n    matchedRules.push('sellerName')\n  }\n\n  // 纳税人识别号\n  m = /购买方纳税人识别号[：: ]*([0-9A-Za-z]{15,20})/.exec(t)\n  if (m) {\n    fields.buyerTaxId = m[1]\n    matchedRules.push('buyerTaxId')\n  }\n  m = /销售方纳税人识别号[：: ]*([0-9A-Za-z]{15,20})/.exec(t)\n  if (m) {\n    fields.sellerTaxId = m[1]\n    matchedRules.push('sellerTaxId')\n  }\n\n  // 查验平台网址\n  m = /查验平台(?:网址)?[：: ]*(https?:\\/\\/[^\\s]+)/.exec(t)\n  if (m) {\n    fields.verifyUrl = m[1]\n    matchedRules.push('verifyUrl')\n  }\n\n  return { fields, matchedRules }\n}\n\n// ---------------------------------------------------------------------------\n// 模型装配与校验\n// ---------------------------------------------------------------------------\n\n/** 关键字段缺失清单（供 confidence 与核对表使用）。 */\nexport function missingKeyFields(fields: RawInvoiceFields): string[] {\n  const missing: string[] = []\n  if (!fields.invoiceNumber) missing.push('发票号码')\n  if (fields.amount === undefined || normalizeMoney(fields.amount) === null) missing.push('金额')\n  if (fields.tax === undefined || normalizeMoney(fields.tax) === null) missing.push('税额')\n  if (fields.total === undefined || normalizeMoney(fields.total) === null) missing.push('价税合计')\n  return missing\n}\n\n/** 所有缺失字段（含次要字段）。 */\nexport function missingFields(fields: RawInvoiceFields): string[] {\n  const missing = missingKeyFields(fields)\n  if (!fields.invoiceCode) missing.push('发票代码')\n  if (!fields.issueDate) missing.push('开票日期')\n  if (!fields.buyerName) missing.push('购买方名称')\n  if (!fields.buyerTaxId) missing.push('购买方税号')\n  if (!fields.sellerName) missing.push('销售方名称')\n  if (!fields.sellerTaxId) missing.push('销售方税号')\n  if (!fields.verifyUrl) missing.push('查验平台')\n  return missing\n}\n\n/** 由原始字段装配 InvoiceData（不做勾稽，勾稽由 validateInvoice 负责）。 */\nexport function buildInvoice(\n  fields: RawInvoiceFields,\n  fileName: string,\n  method: InvoiceSourceMethod,\n  matchedRules?: string[],\n): InvoiceData {\n  const missing = missingFields(fields)\n  const confidence: InvoiceConfidence =\n    (method === 'xml' || method === 'mixed') && missingKeyFields(fields).length === 0\n      ? 'high'\n      : method === 'regex'\n        ? missingKeyFields(fields).length === 0 ? 'medium' : 'low'\n        : missingKeyFields(fields).length === 0 ? 'high' : 'low'\n\n  const invoice: InvoiceData = {\n    invoiceCode: fields.invoiceCode ?? '',\n    invoiceNumber: fields.invoiceNumber ?? '',\n    amount: normalizeMoney(fields.amount ?? '') ?? 0,\n    tax: normalizeMoney(fields.tax ?? '') ?? 0,\n    total: normalizeMoney(fields.total ?? '') ?? 0,\n    issueDate: fields.issueDate ?? '',\n    buyer: { name: fields.buyerName ?? '', taxId: fields.buyerTaxId ?? '' },\n    seller: { name: fields.sellerName ?? '', taxId: fields.sellerTaxId ?? '' },\n    checks: [],\n    source: {\n      file: fileName,\n      method,\n      confidence,\n      missing,\n      matchedRules,\n    },\n  }\n  if (fields.verifyUrl) invoice.verifyUrl = fields.verifyUrl\n  return invoice\n}\n\n/**\n * 勾稽校验：价税合计 = 金额 + 税额（容差 0.01）。\n * 同时校验金额非负、票号 8-20 位数字、日期格式。\n */\nexport function validateInvoice(invoice: InvoiceData): InvoiceCheck[] {\n  const checks: InvoiceCheck[] = []\n  const expected = invoice.amount + invoice.tax\n  const diff = Math.abs(invoice.total - expected)\n  checks.push({\n    label: '勾稽(价税合计=金额+税额)',\n    ok: diff <= TOTAL_TOLERANCE,\n    detail: `合计 ${invoice.total.toFixed(2)} vs 金额+税额 ${expected.toFixed(2)}${diff > TOTAL_TOLERANCE ? `（差 ${diff.toFixed(2)}）` : ''}`,\n  })\n  checks.push({ label: '金额/税额非负', ok: invoice.amount >= 0 && invoice.tax >= 0, detail: `金额 ${invoice.amount.toFixed(2)} / 税额 ${invoice.tax.toFixed(2)}` })\n  checks.push({ label: '票号格式', ok: /^[0-9]{8,20}$/.test(invoice.invoiceNumber), detail: invoice.invoiceNumber || '（空）' })\n  checks.push({ label: '开票日期格式', ok: invoice.issueDate === '' || /^\\d{4}-\\d{2}-\\d{2}$/.test(invoice.issueDate), detail: invoice.issueDate || '（空）' })\n  return checks\n}\n\n/** XML 路径解析：从结构化 XML 抽取字段并装配（可选文本层补齐，method 变 mixed）。 */\nexport function parseInvoiceFromXml(xml: string, fileName: string, fallbackText?: string): InvoiceData {\n  const tags = collectXmlTags(xml)\n  const fields = fieldsFromXmlTags(tags)\n  let method: InvoiceSourceMethod = 'xml'\n  let matchedRules: string[] | undefined\n\n  // XML 缺关键字段且提供文本层时：正则补齐（method -> mixed）\n  const missingKeys = missingKeyFields(fields)\n  if (missingKeys.length > 0 && fallbackText && fallbackText.trim().length > 0) {\n    const textResult = parseInvoiceFromText(fallbackText)\n    matchedRules = textResult.matchedRules\n    for (const key of missingKeys) {\n      const fieldKey = key === '发票号码' ? 'invoiceNumber' : key === '金额' ? 'amount' : key === '税额' ? 'tax' : 'total'\n      const value = textResult.fields[fieldKey as keyof RawInvoiceFields]\n      if (value !== undefined && (fieldKey === 'invoiceNumber' || normalizeMoney(value) !== null)) {\n        fields[fieldKey as keyof RawInvoiceFields] = value\n      }\n    }\n    if (missingKeyFields(fields).length === 0) method = 'mixed'\n  }\n\n  return buildInvoice(fields, fileName, method, matchedRules)\n}\n\n/** 文本正则路径解析。 */\nexport function parseInvoiceFromTextLines(text: string, fileName: string): InvoiceData {\n  const { fields, matchedRules } = parseInvoiceFromText(text)\n  return buildInvoice(fields, fileName, 'regex', matchedRules)\n}"
    },
    {
      "path": "src/pdf-extract.ts",
      "content": "/**\n * pdf-extract.ts — 自写最小 PDF 解析器（离线、零第三方依赖）。\n *\n * 目标：从增值税电子发票（数电票/全电发票）PDF 中提取\n *   1. 内嵌结构化 XML 附件（优先，/EmbeddedFiles 命名树，支持 FlateDecode 或未压缩流）；\n *   2. 文本层（页面 Content 流的 BT..ET 文本操作符，Tj/TJ；支持 latin1 与 UTF-16BE hex 字符串）；\n *   3. 加密/密码保护检测（/Encrypt）。\n *\n * 实现手段：不依赖 xref 表——按顺序扫描 `N G obj` 定义并用 /Length 精确跳过\n * stream 内容（与真实 pdfplumber/pypdf 抽取结果等价的轻量实现），因此对\n * 传统 xref 表与 xref 流（真实数电票常见）均鲁棒。仅使用 Node 内置 zlib。\n *\n * 局限（README 明示）：不支持 JPEG2000/对象流内的间接引用流、不渲染页面；\n * 生产环境如需完整 PDF 语义可替换为调用 pdfplumber/pypdf 的外部路径。\n */\n\nimport { deflateSync, inflateRawSync, inflateSync } from 'node:zlib'\n\n/** PDF 抽取结果。 */\nexport interface PdfExtraction {\n  /** 拼合后的文本层（每\"行文本\"以 \\n 分隔）。 */\n  text: string\n  /** 内嵌附件中解码出的 XML 文档（按附件出现顺序）。 */\n  embeddedXml: string[]\n  /** PDF 是否声明了 /Encrypt（密码保护/加密）。 */\n  encrypted: boolean\n  /** 页面数量（尽量统计；无法确定时为 0）。 */\n  pageCount: number\n}\n\n// ---------------------------------------------------------------------------\n// 字节工具\n// ---------------------------------------------------------------------------\n\n/** 字节 → latin1 字符串（逐字节一一映射，作为定位/词法视图）。 */\nfunction bytesToLatin1(bytes: Uint8Array): string {\n  let out = ''\n  const chunk = 0x8000\n  for (let i = 0; i < bytes.length; i += chunk) {\n    const end = Math.min(i + chunk, bytes.length)\n    out += String.fromCharCode(...bytes.subarray(i, end))\n  }\n  return out\n}\n\n/** latin1 字符串 → 字节。 */\nfunction latin1ToBytes(str: string): Uint8Array {\n  const bytes = new Uint8Array(str.length)\n  for (let i = 0; i < str.length; i++) bytes[i] = str.charCodeAt(i) & 0xff\n  return bytes\n}\n\n/** latin1 解码。 */\nfunction decodeLatin1(bytes: Uint8Array): string {\n  let out = ''\n  for (let i = 0; i < bytes.length; i++) out += String.fromCharCode(bytes[i])\n  return out\n}\n\n/** 尝试多种解码：优先 UTF-16BE（带 BOM），否则 latin1。 */\nfunction decodePossiblyUtf16(bytes: Uint8Array): string {\n  if (bytes.length >= 2 && bytes[0] === 0xfe && bytes[1] === 0xff) {\n    const out: string[] = []\n    for (let i = 2; i + 1 < bytes.length; i += 2) {\n      out.push(String.fromCharCode((bytes[i] << 8) | bytes[i + 1]))\n    }\n    return out.join('')\n  }\n  return decodeLatin1(bytes)\n}\n\n// ---------------------------------------------------------------------------\n// PDF 值词法\n// ---------------------------------------------------------------------------\n\ntype PdfValue =\n  | { kind: 'name'; name: string }\n  | { kind: 'string'; text: string }\n  | { kind: 'number'; num: number }\n  | { kind: 'ref'; num: number; gen: number }\n  | { kind: 'array'; items: PdfValue[] }\n  | { kind: 'dict'; dict: Record<string, PdfValue> }\n  | { kind: 'bool'; value: boolean }\n  | { kind: 'null' }\n\nfunction isName(v: PdfValue | undefined, name: string): boolean {\n  return v !== undefined && v.kind === 'name' && v.name === name\n}\n\nfunction nameOf(v: PdfValue | undefined): string | undefined {\n  return v !== undefined && v.kind === 'name' ? v.name : undefined\n}\n\nfunction stringOf(v: PdfValue | undefined): string | undefined {\n  return v !== undefined && v.kind === 'string' ? v.text : undefined\n}\n\nfunction numberOf(v: PdfValue | undefined): number | undefined {\n  return v !== undefined && v.kind === 'number' ? v.num : undefined\n}\n\n/** 解析 PDF 普通字符串 (..)，处理 \\n \\r \\t \\b \\f \\( \\) \\\\ 与 \\ddd 八进制。 */\nfunction parsePdfString(str: string, start: number): { text: string; end: number } {\n  let i = start + 1 // 跳过 (\n  const out: string[] = []\n  while (i < str.length) {\n    const c = str[i]\n    if (c === ')') return { text: out.join(''), end: i + 1 }\n    if (c === '\\\\') {\n      const n = str[i + 1]\n      switch (n) {\n        case 'n': out.push('\\n'); i += 2; break\n        case 'r': out.push('\\r'); i += 2; break\n        case 't': out.push('\\t'); i += 2; break\n        case 'b': out.push('\\b'); i += 2; break\n        case 'f': out.push('\\f'); i += 2; break\n        case '(': out.push('('); i += 2; break\n        case ')': out.push(')'); i += 2; break\n        case '\\\\': out.push('\\\\'); i += 2; break\n        case '\\r':\n          i += str[i + 1] === '\\n' ? 2 : 1\n          break\n        case '\\n':\n          i += 1\n          break\n        default: {\n          // \\ddd 八进制（1-3 位）\n          let codeStr = ''\n          let j = i + 1\n          while (j < str.length && codeStr.length < 3 && str[j] >= '0' && str[j] <= '7') {\n            codeStr += str[j]\n            j++\n          }\n          if (codeStr.length > 0) {\n            out.push(String.fromCharCode(parseInt(codeStr, 8) & 0xff))\n            i = j\n          } else {\n            i += 2\n          }\n        }\n      }\n    } else {\n      out.push(c)\n      i++\n    }\n  }\n  return { text: out.join(''), end: str.length }\n}\n\n/**\n * 解析一个 PDF 值（从 pos 处开始）。支持 name/string/hex-string/array/dict/number/ref/bool/null。\n * 返回 { value, end }；无法识别类型时返回 { value: undefined, end: pos }。\n */\nfunction parsePdfValueAt(str: string, pos: number): { value: PdfValue | undefined; end: number } {\n  const skipWs = (p: number): number => {\n    while (p < str.length && /[\\x00-\\x20]/.test(str[p])) p++\n    return p\n  }\n  let p = skipWs(pos)\n  const c = str[p]\n  if (c === '/') {\n    const m = /^[A-Za-z0-9._\\-!#$&*+,:;=?@|~]+/.exec(str.slice(p + 1))\n    if (!m) return { value: undefined, end: p }\n    return { value: { kind: 'name', name: m[0] }, end: p + 1 + m[0].length }\n  }\n  if (c === '(') {\n    const r = parsePdfString(str, p)\n    return { value: { kind: 'string', text: r.text }, end: r.end }\n  }\n  if (c === '<') {\n    if (str[p + 1] === '<') {\n      // 嵌套字典：包装为 { value: { kind: 'dict', ... }, end }，不能直接透传 parsePdfDictAt 的返回形状\n      const d = parsePdfDictAt(str, p)\n      return d.dict === undefined\n        ? { value: undefined, end: d.end }\n        : { value: { kind: 'dict', dict: d.dict }, end: d.end }\n    }\n    // hex string <...>\n    const close = str.indexOf('>', p + 1)\n    if (close < 0) return { value: undefined, end: p }\n    const hex = str.slice(p + 1, close).replace(/[\\s]/g, '')\n    const bytes = new Uint8Array(Math.ceil(hex.length / 2))\n    for (let i = 0; i < bytes.length; i++) {\n      const h = hex.slice(i * 2, i * 2 + 2)\n      bytes[i] = parseInt(h.padEnd(2, '0'), 16) || 0\n    }\n    return { value: { kind: 'string', text: decodePossiblyUtf16(bytes) }, end: close + 1 }\n  }\n  if (c === '[') {\n    const items: PdfValue[] = []\n    let q = p + 1\n    for (;;) {\n      q = skipWs(q)\n      if (q >= str.length) return { value: undefined, end: q }\n      if (str[q] === ']') return { value: { kind: 'array', items }, end: q + 1 }\n      const r = parsePdfValueAt(str, q)\n      if (r.value === undefined) q = skipWs(q + 1)\n      else {\n        items.push(r.value)\n        q = r.end\n      }\n    }\n  }\n  if (c === 't' && str.startsWith('true', p)) return { value: { kind: 'bool', value: true }, end: p + 4 }\n  if (c === 'f' && str.startsWith('false', p)) return { value: { kind: 'bool', value: false }, end: p + 5 }\n  if (c === 'n' && str.startsWith('null', p)) return { value: { kind: 'null' }, end: p + 4 }\n  if (c === '-' || c === '+' || c === '.' || (c >= '0' && c <= '9')) {\n    const m = /^[+-]?(\\d+(?:\\.\\d+)?)(?=[\\s\\]\\/>])/.exec(str.slice(p))\n    if (!m) return { value: undefined, end: p }\n    const raw = m[0]\n    const after = skipWs(p + raw.length)\n    // 间接引用形式 \"N G R\"：raw 是 N，后面再跟一个整数 G 与 R\n    const refM = /^(\\d+)\\s+R/.exec(str.slice(after))\n    if (refM) {\n      return { value: { kind: 'ref', num: parseFloat(raw), gen: parseInt(refM[1], 10) }, end: after + refM[0].length }\n    }\n    if (str[after] === 'R') {\n      return { value: { kind: 'ref', num: parseFloat(raw), gen: 0 }, end: after + 1 }\n    }\n    return { value: { kind: 'number', num: parseFloat(raw) }, end: p + raw.length }\n  }\n  return { value: undefined, end: p }\n}\n\n/** 解析 PDF 字典 << ... >>，返回 { dict, end }；非字典起始时返回 { dict: undefined, end: pos }。 */\nfunction parsePdfDictAt(str: string, pos: number): { dict: Record<string, PdfValue> | undefined; end: number } {\n  const skipWs = (p: number): number => {\n    while (p < str.length && /[\\x00-\\x20]/.test(str[p])) p++\n    return p\n  }\n  let p = skipWs(pos)\n  if (!str.startsWith('<<', p)) return { dict: undefined, end: p }\n  const dict: Record<string, PdfValue> = {}\n  p = skipWs(p + 2)\n  for (;;) {\n    if (p >= str.length) return { dict: undefined, end: str.length }\n    // 闭合 >> 处返回\n    if (str[p] === '>' && str[p + 1] === '>') return { dict, end: p + 2 }\n    // 期望 key（/Name）；异常容错：前进到下一个 '/' 或闭合 '>>'\n    if (str[p] !== '/') {\n      const nextSlash = str.indexOf('/', p + 1)\n      const nextClose = str.indexOf('>>', p)\n      if (nextClose >= 0 && (nextSlash < 0 || nextClose < nextSlash)) {\n        p = nextClose\n        continue\n      }\n      if (nextSlash >= 0) {\n        p = nextSlash\n        continue\n      }\n      return { dict: undefined, end: str.length }\n    }\n    const keyMatch = /^[A-Za-z0-9._\\-!#$&*+,:;=?@|~]+/.exec(str.slice(p + 1))\n    if (!keyMatch) return { dict: undefined, end: p }\n    const key = keyMatch[0]\n    p = skipWs(p + 1 + key.length)\n    const r = parsePdfValueAt(str, p)\n    if (r.value === undefined) {\n      // 缺值：跳到下一个 '/' 继续\n      const nextSlash = str.indexOf('/', p + 1)\n      if (nextSlash < 0) return { dict: undefined, end: str.length }\n      p = nextSlash\n      continue\n    }\n    dict[key] = r.value\n    p = skipWs(r.end)\n  }\n}\n\n// ---------------------------------------------------------------------------\n// 顶层扫描与流提取\n// ---------------------------------------------------------------------------\n\ninterface ScannedObject {\n  num: number\n  gen: number\n  /** 对象 dict（可能无）。 */\n  dict?: Record<string, PdfValue>\n  /** stream 数据字节区间（-1 表示非流对象）。 */\n  streamStart: number\n  streamEnd: number\n  /** 对象开始偏移。 */\n  start: number\n}\n\nconst WS_RE = /^[\\x00-\\x20\\r\\n\\t\\f]*/\n\n/** 在 latin1 视图中查找 \"stream\" 关键字并返回流字节起始（跳过 CRLF）。\n *  limit 用于约束\"紧邻字典之后\"的位置，避免误把远处对象的 stream 关键字当成本对象的。 */\nfunction findStreamStart(latin: string, from: number, limit?: number): number {\n  const idx = latin.indexOf('stream', from)\n  if (idx < 0) return -1\n  if (limit !== undefined && idx > from + limit) return -1\n  let p = idx + 'stream'.length\n  if (latin[p] === '\\r') p++\n  if (latin[p] === '\\n') p++\n  return p\n}\n\n/**\n * 顺序扫描全部顶层对象。用 /Length（直接数字）或 \"下一个 endstream\" 定位流边界，\n * 从而跳过流内容，规避流内 \"N G obj\" 误报。\n */\nfunction scanObjects(bytes: Uint8Array): ScannedObject[] {\n  const latin = bytesToLatin1(bytes)\n  const objs: ScannedObject[] = []\n  const RE = /(\\d{1,6})\\s+(\\d{1,6})\\s+obj/g\n  let skipUntil = 0\n  let m: RegExpExecArray | null\n  while ((m = RE.exec(latin)) !== null) {\n    const start = m.index\n    if (start < skipUntil) {\n      RE.lastIndex = Math.max(RE.lastIndex, skipUntil)\n      continue\n    }\n    const num = parseInt(m[1], 10)\n    const gen = parseInt(m[2], 10)\n    // 解析对象体：dict 或标量\n    const dictStart = m.index + m[0].length\n    const head = latin.slice(dictStart).replace(WS_RE, '')\n    const headOffset = dictStart + (latin.slice(dictStart).length - head.length)\n    const dictResult = /^<</.test(head) ? parsePdfDictAt(latin, headOffset) : undefined\n    let streamStart = -1\n    let streamEnd = -1\n    let nextPos: number\n    if (dictResult && dictResult.dict !== undefined) {\n      const streamPos = findStreamStart(latin, dictResult.end, 24)\n      if (streamPos >= 0) {\n        // 有 stream：长度优先用 /Length，其次找 endstream\n        let length = numberOf(dictResult.dict['Length'])\n        if (length !== undefined && length >= 0) {\n          streamStart = streamPos\n          streamEnd = streamPos + length\n          nextPos = streamEnd\n        } else {\n          const es = latin.indexOf('endstream', streamPos)\n          streamStart = streamPos\n          streamEnd = es >= 0 ? es : streamPos\n          nextPos = es >= 0 ? es : streamPos\n        }\n        if (length === undefined) {\n          // /Length 引用或缺失：确认 endstream 紧跟在流后\n          const es = latin.indexOf('endstream', streamEnd)\n          if (es >= 0 && es - streamEnd <= 4) nextPos = es\n        }\n      } else {\n        nextPos = dictResult.end\n      }\n      objs.push({ num, gen, dict: dictResult.dict, streamStart, streamEnd, start })\n      // 跳过流内容，防止误报\n      skipUntil = streamEnd > 0 ? streamEnd + 10 : dictResult.end + 8\n    } else {\n      // 标量对象：跳到 endobj\n      const endobj = latin.indexOf('endobj', headOffset)\n      nextPos = endobj >= 0 ? endobj : headOffset + 8\n      objs.push({ num, gen, streamStart, streamEnd, start })\n      skipUntil = nextPos + 8\n    }\n    if (RE.lastIndex < nextPos) RE.lastIndex = Math.max(RE.lastIndex + 1, nextPos)\n  }\n  // 归并重复编号（取最后一个出现的对象，通常最完整）\n  const byNum = new Map<number, ScannedObject>()\n  for (const obj of objs) byNum.set(obj.num, obj)\n  return [...byNum.values()].sort((a, b) => a.start - b.start)\n}\n\n/** 获取指定对象号的流字节（若为流对象）。 */\nfunction getStreamBytes(bytes: Uint8Array, objs: ScannedObject[], num: number): Uint8Array | undefined {\n  const obj = objs.find((o) => o.num === num)\n  if (!obj || obj.streamStart < 0 || obj.streamEnd <= obj.streamStart) return undefined\n  return bytes.subarray(Math.max(0, obj.streamStart), Math.min(bytes.length, obj.streamEnd))\n}\n\n/** 按 /Filter 链解码流（支持 FlateDecode / Fl / Flate；失败时回退原样）。 */\nfunction decodeStream(bytes: Uint8Array): Uint8Array {\n  try {\n    return inflateSync(bytes)\n  } catch {\n    try {\n      return inflateRawSync(bytes)\n    } catch {\n      return bytes\n    }\n  }\n}\n\nfunction filterChainOf(dict: Record<string, PdfValue> | undefined): string[] {\n  if (!dict) return []\n  const f = dict['Filter']\n  if (!f) return []\n  if (f.kind === 'name') return [f.name]\n  if (f.kind === 'array') return f.items.filter((x) => x.kind === 'name').map((x) => (x as { name: string }).name)\n  return []\n}\n\nfunction applyFilterChain(bytes: Uint8Array, filters: string[]): Uint8Array {\n  let data = bytes\n  for (const f of filters) {\n    // 本版仅实现 FlateDecode；未知过滤器保持原样（上层会对不可解码内容降级处理）\n    if (f === 'FlateDecode' || f === 'Fl') data = decodeStream(data)\n  }\n  return data\n}\n\nfunction dictValueText(v: PdfValue | undefined): string {\n  if (!v) return ''\n  if (v.kind === 'string' || v.kind === 'name') return v.kind === 'string' ? v.text : v.name\n  if (v.kind === 'number') return String(v.num)\n  return ''\n}\n\n// ---------------------------------------------------------------------------\n// 内容流文本抽取\n// ---------------------------------------------------------------------------\n\n/**\n * 从单个页面 Content 流文本中抽取文本行。\n * 词法：BT..ET 块内收集字符串操作数（latin1 或 hex UTF-16BE 已在上层规整），\n * Tj 与 TJ 输出；Td、TD、T*、Tm 视为换行分隔。\n */\nfunction extractContentText(contentLatin: string): string {\n  const lines: string[] = []\n  let pos = 0\n  while (pos < contentLatin.length) {\n    const bt = contentLatin.indexOf('BT', pos)\n    if (bt < 0) break\n    const et = contentLatin.indexOf('ET', bt + 2)\n    if (et < 0) break\n    pos = et + 2\n    const block = contentLatin.slice(bt + 2, et)\n\n    // tokenize：字符串 / 数组（递归）/ 数字 / 名字 / 操作符\n    const tokens: ({ kind: 'str'; value: string } | { kind: 'arr'; value: string[] } | { kind: 'op'; value: string })[] = []\n    let i = 0\n    while (i < block.length) {\n      const c = block[i]\n      if (c === '%') {\n        const nl = block.indexOf('\\n', i)\n        i = nl < 0 ? block.length : nl + 1\n        continue\n      }\n      if (/[\\x00-\\x20]/.test(c)) { i++; continue }\n      if (c === '(') {\n        const r = parsePdfString(block, i)\n        tokens.push({ kind: 'str', value: r.text })\n        i = r.end\n        continue\n      }\n      if (c === '<') {\n        // hex string\n        const close = block.indexOf('>', i + 1)\n        if (close < 0) break\n        const hex = block.slice(i + 1, close).replace(/[\\s]/g, '')\n        const b = new Uint8Array(Math.ceil(hex.length / 2))\n        for (let k = 0; k < b.length; k++) {\n          const h = hex.slice(k * 2, k * 2 + 2)\n          b[k] = parseInt(h.padEnd(2, '0'), 16) || 0\n        }\n        tokens.push({ kind: 'str', value: decodePossiblyUtf16(b) })\n        i = close + 1\n        continue\n      }\n      if (c === '[') {\n        const items: string[] = []\n        let j = i + 1\n        while (j < block.length && block[j] !== ']') {\n          if (block[j] === '(') {\n            const r = parsePdfString(block, j)\n            items.push(r.text)\n            j = r.end\n          } else if (/^<[0-9A-Fa-f\\s]+>$/.test(block.slice(j, block.indexOf('>', j) + 1))) {\n            const close = block.indexOf('>', j)\n            const hex = block.slice(j + 1, close).replace(/[\\s]/g, '')\n            const b = new Uint8Array(Math.ceil(hex.length / 2))\n            for (let k = 0; k < b.length; k++) {\n              const h = hex.slice(k * 2, k * 2 + 2)\n              b[k] = parseInt(h.padEnd(2, '0'), 16) || 0\n            }\n            items.push(decodePossiblyUtf16(b))\n            j = close + 1\n          } else {\n            j++\n          }\n        }\n        tokens.push({ kind: 'arr', value: items })\n        i = j + 1\n        continue\n      }\n      if (c === '/') {\n        const m = /^[A-Za-z0-9._\\-]+/.exec(block.slice(i + 1))\n        if (!m) { i++; continue }\n        i = i + 1 + m[0].length\n        continue\n      }\n      if (c === '-' || c === '+' || c === '.' || (c >= '0' && c <= '9')) {\n        const m = /^[+-]?[\\d.]+/.exec(block.slice(i))\n        if (m) i += m[0].length\n        else i++\n        continue\n      }\n      // 操作符（字母序列）\n      const m = /^[A-Za-z*'\"]+/.exec(block.slice(i))\n      if (m) {\n        tokens.push({ kind: 'op', value: m[0] })\n        i += m[0].length\n      } else i++\n    }\n\n    // 依操作符装配文本行\n    let pending: string[] = []\n    let pendingArr: string[] | null = null\n    const flush = () => {\n      if (pending.length > 0 || (pendingArr !== null && pendingArr.length > 0)) {\n        const joined = pendingArr !== null ? pendingArr.join('') : pending.join('')\n        if (joined.length > 0) lines.push(joined)\n      }\n      pending = []\n      pendingArr = null\n    }\n    for (let k = 0; k < tokens.length; k++) {\n      const tkn = tokens[k]\n      if (tkn.kind === 'str') pending.push(tkn.value)\n      else if (tkn.kind === 'arr') pendingArr = tkn.value\n      else {\n        const op = tkn.value as string\n        if (op === 'Tj') flush()\n        else if (op === 'TJ') flush()\n        else if (op === 'Td' || op === 'TD' || op === 'T*' || op === 'Tm') {\n          flush()\n          // 末尾标记新行（下一段文本前）\n          pending = []\n        } else if (op === 'ET') flush()\n      }\n    }\n    flush()\n  }\n  return lines.join('\\n')\n}\n\n// ---------------------------------------------------------------------------\n// EmbeddedFiles 附件提取\n// ---------------------------------------------------------------------------\n\n/** 从扫描对象中提取 /EmbeddedFiles 命名树里的全部附件（name → 文本内容）。 */\nfunction extractEmbeddedXml(bytes: Uint8Array, objs: ScannedObject[]): { name: string; text: string }[] {\n  const out: { name: string; text: string }[] = []\n  for (const obj of objs) {\n    if (!obj.dict) continue\n    // /EmbeddedFiles 可能直接挂在对象下（如 Catalog 的 /Names 子树内）\n    let embedded: PdfValue | undefined = obj.dict['EmbeddedFiles']\n    if (embedded === undefined || embedded.kind === 'null') {\n      const names = obj.dict['Names']\n      embedded = names !== undefined && names.kind === 'dict' ? names.dict['EmbeddedFiles'] : undefined\n    }\n    if (!embedded || embedded.kind === 'null') continue\n    if (embedded.kind === 'dict') {\n      // 命名树：/Names [ (a) ref (b) ref ... ]\n      const namesArr = embedded.dict['Names']\n      if (!namesArr || namesArr.kind !== 'array') continue\n      const items = namesArr.items\n      for (let k = 0; k + 1 < items.length; k += 2) {\n        const nameVal = items[k]\n        const refVal