   if (obj.dict && isName(obj.dict['Type'], 'Page')) pageNums.push(obj.num)\n  }\n  const pageTexts: string[] = []\n  for (const pageNum of pageNums) {\n    const page = objs.find((o) => o.num === pageNum)\n    if (!page || !page.dict) continue\n    const contents = page.dict['Contents']\n    const refs: number[] = []\n    if (contents && contents.kind === 'ref') refs.push(contents.num)\n    else if (contents && contents.kind === 'array') {\n      for (const item of contents.items) if (item.kind === 'ref') refs.push(item.num)\n    }\n    for (const ref of refs) {\n      const raw = getStreamBytes(bytes, objs, ref)\n      if (!raw) continue\n      const decoded = applyFilterChain(raw, filterChainOf(objs.find((o) => o.num === ref)?.dict))\n      const text = extractContentText(decodePossiblyUtf16(decoded))\n      if (text.length > 0) pageTexts.push(text)\n    }\n  }\n  const text = pageTexts.join('\\n').trim()\n\n  // XML 附件\n  const xmls = extractEmbeddedXml(bytes, objs).map((x) => x.text)\n\n  return { text, embeddedXml: xmls, encrypted, pageCount: pageNums.length }\n}\n\n/** 判断文件类型（读头字节，避免整读）：pdf / png / jpg / other。 */\nexport function detectFileKind(bytes: Uint8Array, fileName: string): 'pdf' | 'png' | 'jpg' | 'other' {\n  const base = fileName.toLowerCase()\n  const isPdfMagic = bytes.length >= 5 && bytes[0] === 0x25 && bytes[1] === 0x50 && bytes[2] === 0x44 && bytes[3] === 0x46 && bytes[4] === 0x2d\n  if (isPdfMagic) return 'pdf'\n  if (bytes.length >= 8 && bytes[0] === 0x89 && bytes[1] === 0x50 && bytes[2] === 0x4e && bytes[3] === 0x47) return 'png'\n  if (bytes.length >= 3 && bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff) return 'jpg'\n  if (base.endsWith('.pdf')) return 'pdf'\n  if (base.endsWith('.png')) return 'png'\n  if (base.endsWith('.jpg') || base.endsWith('.jpeg')) return 'jpg'\n  return 'other'\n}\n\n/** 供测试与生产复用：把 UTF-8 文本压缩进 PDF 流所需的 Flate 编码（保持对称，供 fixture 生成器使用）。 */\nexport { deflateSync as deflateFlate }"
