    {
      "path": "src/summary.ts",
      "content": "/**\n * summary.ts — 汇总结算与报销单渲染（纯逻辑，零第三方依赖）。\n *\n *  - summarizeInvoices：合计/税额/价税合计、按类别小计、重复票检测（同票号+同金额）；\n *  - renderMarkdown：报销单 Markdown（工作区可直接打开）；\n *  - renderXlsx：最小 xlsx（ZIP + OOXML），可由 Excel/WPS/openpyxl 打开；\n *  - buildZip：自写极小 ZIP 打包器（内置 zlib.deflateSync，无任何 npm 依赖）。\n */\n\nimport { deflateRawSync } from 'node:zlib'\nimport type { InvoiceData } from './invoice-model.ts'\n\n// ---------------------------------------------------------------------------\n// 汇总\n// ---------------------------------------------------------------------------\n\n/** 汇总合计。 */\nexport interface SummaryTotals {\n  count: number\n  amount: number\n  tax: number\n  total: number\n}\n\n/** 重复票分组：同票号 + 同金额（保留首张，其余 flagged）。 */\nexport interface DuplicateGroup {\n  key: string\n  invoiceNumber: string\n  amount: number\n  files: string[]\n  /** 被判定为重复（应剔除）的源文件名。 */\n  flagged: string[]\n}\n\n/** 按类别小计行。 */\nexport interface CategoryTotal {\n  category: string\n  count: number\n  amount: number\n  tax: number\n  total: number\n}\n\n/** 完整汇总结果。 */\nexport interface InvoiceSummary {\n  totals: SummaryTotals\n  byCategory: CategoryTotal[]\n  duplicates: DuplicateGroup[]\n}\n\n/** 金额四舍五入到分。 */\nfunction round2(n: number): number {\n  return Math.round(n * 100) / 100\n}\n\n/** 汇总结算 + 重复检测。 */\nexport function summarizeInvoices(invoices: InvoiceData[]): InvoiceSummary {\n  const totals: SummaryTotals = { count: invoices.length, amount: 0, tax: 0, total: 0 }\n  const catMap = new Map<string, CategoryTotal>()\n  const dupMap = new Map<string, DuplicateGroup>()\n\n  for (const inv of invoices) {\n    totals.amount = round2(totals.amount + inv.amount)\n    totals.tax = round2(totals.tax + inv.tax)\n    totals.total = round2(totals.total + inv.total)\n\n    const cat = inv.category ?? '未分类'\n    const entry = catMap.get(cat) ?? { category: cat, count: 0, amount: 0, tax: 0, total: 0 }\n    entry.count += 1\n    entry.amount = round2(entry.amount + inv.amount)\n    entry.tax = round2(entry.tax + inv.tax)\n    entry.total = round2(entry.total + inv.total)\n    catMap.set(cat, entry)\n\n    if (/^[0-9]{8,20}$/.test(inv.invoiceNumber)) {\n      const key = `${inv.invoiceNumber}@${inv.amount.toFixed(2)}`\n      const group = dupMap.get(key) ?? {\n        key,\n        invoiceNumber: inv.invoiceNumber,\n        amount: inv.amount,\n        files: [],\n        flagged: [],\n      }\n      group.files.push(inv.source.file)\n      dupMap.set(key, group)\n    }\n  }\n\n  const duplicates: DuplicateGroup[] = [...dupMap.values()]\n    .filter((g) => g.files.length > 1)\n    .map((g) => ({ ...g, flagged: g.files.slice(1) }))\n\n  return { totals, byCategory: [...catMap.values()], duplicates }\n}\n\n// ---------------------------------------------------------------------------\n// Markdown 渲染\n// ---------------------------------------------------------------------------\n\n/** 渲染报销单 Markdown。 */\nexport function renderMarkdown(invoices: InvoiceData[], summary: InvoiceSummary, opts?: { title?: string; generatedAt?: string }): string {\n  const title = opts?.title ?? '报销单'\n  const generatedAt = opts?.generatedAt ?? new Date().toISOString()\n  const t = summary.totals\n  const lines: string[] = []\n  lines.push(`# ${title}`)\n  lines.push('')\n  lines.push(`> 由 dsh-invoice-tools 生成 · ${generatedAt}`)\n  lines.push('> ')\n  lines.push(`> 发票共 **${t.count}** 张，金额合计 **¥${t.amount.toFixed(2)}**，税额合计 **¥${t.tax.toFixed(2)}**，价税合计 **¥${t.total.toFixed(2)}**`)\n  if (summary.duplicates.length > 0) {\n    lines.push('> ')\n    lines.push(`> ⚠ 重复票提示：${summary.duplicates.map((d) => `${d.invoiceNumber}（${d.flagged.join('、')}）`).join('；')} —— 建议剔除后报销。`)\n  }\n  lines.push('')\n  lines.push('| # | 发票号码 | 发票代码 | 开票日期 | 销售方 | 金额 | 税额 | 价税合计 | 类别 | 源文件 |')\n  lines.push('| --- | --- | --- | --- | --- | ---: | ---: | ---: | --- | --- |')\n  invoices.forEach((inv, idx) => {\n    const flag = summary.duplicates.some((d) => d.flagged.includes(inv.source.file)) ? ' ⚠重复' : ''\n    lines.push(\n      `| ${idx + 1} | ${inv.invoiceNumber} | ${inv.invoiceCode || '—'} | ${inv.issueDate} | ${inv.seller.name || '—'} | ${inv.amount.toFixed(2)} | ${inv.tax.toFixed(2)} | ${inv.total.toFixed(2)} | ${inv.category ?? '未分类'} | ${inv.source.file}${flag} |`,\n    )\n  })\n  lines.push(\n    `| **合计** | | | | | **${t.amount.toFixed(2)}** | **${t.tax.toFixed(2)}** | **${t.total.toFixed(2)}** | | |`,\n  )\n\n  if (summary.byCategory.length > 1 || summary.byCategory[0]?.category !== '未分类') {\n    lines.push('')\n    lines.push('## 分类小计')\n    lines.push('')\n    lines.push('| 类别 | 张数 | 金额 | 税额 | 价税合计 |')\n    lines.push('| --- | ---: | ---: | ---: | ---: |')\n    for (const c of summary.byCategory) {\n      lines.push(`| ${c.category} | ${c.count} | ${c.amount.toFixed(2)} | ${c.tax.toFixed(2)} | ${c.total.toFixed(2)} |`)\n    }\n  }\n\n  lines.push('')\n  lines.push('---')\n  lines.push('')\n  lines.push('报销人：________　　审批人：________　　日期：________')\n  lines.push('')\n  lines.push('> 隐私说明：发票数据仅在本地会话/工作区流转，本工具不发起任何查验接口请求。')\n  return lines.join('\\n')\n}\n\n// ---------------------------------------------------------------------------\n// 最小 xlsx（含 zip 打包）\n// ---------------------------------------------------------------------------\n\n/** XML 转义。 */\nfunction xmlEscape(s: string): string {\n  return s\n    .replace(/&/g, '&amp;')\n    .replace(/</g, '&lt;')\n    .replace(/>/g, '&gt;')\n    .replace(/\"/g, '&quot;')\n    .replace(/'/g, '&apos;')\n}\n\nfunction textEncode(str: string): Uint8Array {\n  return new TextEncoder().encode(str)\n}\n\nconst CRC_TABLE = (() => {\n  const table = new Uint32Array(256)\n  for (let n = 0; n < 256; n++) {\n    let c = n\n    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1\n    table[n] = c >>> 0\n  }\n  return table\n})()\n\nfunction crc32(bytes: Uint8Array): number {\n  let crc = 0xffffffff\n  for (let i = 0; i < bytes.length; i++) {\n    crc = CRC_TABLE[(crc ^ bytes[i]) & 0xff] ^ (crc >>> 8)\n  }\n  return (crc ^ 0xffffffff) >>> 0\n}\n\nfunction dosDateTime(date: Date): { time: number; date: number } {\n  const time = (date.getHours() << 11) | (date.getMinutes() << 5) | (date.getSeconds() >> 1)\n  const d = ((date.getFullYear() - 1980) << 9) | ((date.getMonth() + 1) << 5) | date.getDate()\n  return { time, date: d }\n}\n\n/** 自写极小 ZIP 打包器（store/deflate 混合不可用，统一 deflate，条目名 UTF-8）。 */\nexport function buildZip(files: { name: string; data: Uint8Array }[]): Uint8Array {\n  const pieces: Uint8Array[] = []\n  const central: Uint8Array[] = []\n  let offset = 0\n  const now = new Date()\n  const { time, date } = dosDateTime(now)\n\n  for (const file of files) {\n    const nameBytes = textEncode(file.name)\n    const compressed = deflateRawSync(file.data, { level: 6 })\n    const crc = crc32(file.data)\n\n    const localHeader = new Uint8Array(30)\n    const dv = new DataView(localHeader.buffer)\n    dv.setUint32(0, 0x04034b50, true)\n    dv.setUint16(4, 20, true) // version needed\n    dv.setUint16(6, 0x0800, true) // UTF-8 flag\n    dv.setUint16(8, 8, true) // method: deflate\n    dv.setUint16(10, time, true)\n    dv.setUint16(12, date, true)\n    dv.setUint32(14, crc, true)\n    dv.setUint32(18, compressed.length, true)\n    dv.setUint32(22, file.data.length, true)\n    dv.setUint16(26, nameBytes.length, true)\n    dv.setUint16(28, 0, true)\n\n    pieces.push(localHeader, nameBytes, compressed)\n\n    const cd = new Uint8Array(46)\n    const cdv = new DataView(cd.buffer)\n    cdv.setUint32(0, 0x02014b50, true)\n    cdv.setUint16(4, 20, true)\n    cdv.setUint16(6, 20, true)\n    cdv.setUint16(8, 0x0800, true)\n    cdv.setUint16(10, 8, true)\n    cdv.setUint16(12, time, true)\n    cdv.setUint16(14, date, true)\n    cdv.setUint32(16, crc, true)\n    cdv.setUint32(20, compressed.length, true)\n    cdv.setUint32(24, file.data.length, true)\n    cdv.setUint16(28, nameBytes.length, true)\n    cdv.setUint32(42, offset, true)\n    central.push(cd, nameBytes)\n    offset += 30 + nameBytes.length + compressed.length\n  }\n\n  const centralSize = central.reduce((acc, c) => acc + c.length, 0)\n  const centralOffset = offset\n\n  const eocd = new Uint8Array(22)\n  const edv = new DataView(eocd.buffer)\n  edv.setUint32(0, 0x06054b50, true)\n  edv.setUint16(8, files.length, true)\n  edv.setUint16(10, files.length, true)\n  edv.setUint32(12, centralSize, true)\n  edv.setUint32(16, centralOffset, true)\n\n  const totalLength = offset + centralSize + 22\n  const out = new Uint8Array(totalLength)\n  let w = 0\n  for (const p of pieces) {\n    out.set(p, w)\n    w += p.length\n  }\n  for (const c of central) {\n    out.set(c, w)\n    w += c.length\n  }\n  out.set(eocd, w)\n  return out\n}\n\n/** 渲染工作表单元格（inlineStr 字符串 / 原生数字）。 */\nfunction cellXml(ref: string, value: string | number): string {\n  if (typeof value === 'number') {\n    return `<c r=\"${ref}\"><v>${value.toFixed(2)}</v></c>`\n  }\n  return `<c r=\"${ref}\" t=\"inlineStr\"><is><t xml:space=\"preserve\">${xmlEscape(value)}</t></is></c>`\n}\n\nfunction colName(index: number): string {\n  let n = index\n  let s = ''\n  while (n >= 0) {\n    s = String.fromCharCode(65 + (n % 26)) + s\n    n = Math.floor(n / 26) - 1\n  }\n  return s\n}\n\n/** 渲染 xlsx 字节（单 sheet\"报销单\"）。 */\nexport function renderXlsx(invoices: InvoiceData[], summary: InvoiceSummary): Uint8Array {\n  const headers = ['#', '发票号码', '发票代码', '开票日期', '销售方', '购买方', '金额', '税额', '价税合计', '类别', '源文件']\n  const rows: (string | number)[][] = []\n  invoices.forEach((inv, idx) => {\n    rows.push([\n      idx + 1,\n      inv.invoiceNumber,\n      inv.invoiceCode,\n      inv.issueDate,\n      inv.seller.name,\n      inv.buyer.name,\n      inv.amount,\n      inv.tax,\n      inv.total,\n      inv.category ?? '未分类',\n      inv.source.file,\n    ])\n  })\n  rows.push(['合计', '', '', '', '', '', summary.totals.amount, summary.totals.tax, summary.totals.total, '', `${summary.totals.count} 张`])\n\n  let sheet = '<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>\\n'\n  sheet += `<worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetData>`\n  sheet += `<row r=\"1\">${headers.map((h, i) => cellXml(`${colName(i)}1`, h)).join('')}</row>`\n  rows.forEach((row, r) => {\n    const rowNum = r + 2\n    sheet += `<row r=\"${rowNum}\">${row.map((v, i) => cellXml(`${colName(i)}${rowNum}`, v)).join('')}</row>`\n  })\n  sheet += `</sheetData></worksheet>`\n\n  const contentTypes = `<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>\n<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\">\n<Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/>\n<Default Extension=\"xml\" ContentType=\"application/xml\"/>\n<Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/>\n<Override PartName=\"/xl/worksheets/sheet1.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/>\n<Override PartName=\"/xl/styles.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml\"/>\n<Override PartName=\"/docProps/core.xml\" ContentType=\"application/vnd.openxmlformats-package.core-properties+xml\"/>\n<Override PartName=\"/docProps/app.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.extended-properties+xml\"/>\n</Types>`\n\n  const rels = `<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>\n<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">\n<Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/>\n<Relationship Id=\"rId2\" Type=\"http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties\" Target=\"docProps/core.xml\"/>\n<Relationship Id=\"rId3\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/extended-properties\" Target=\"docProps/app.xml\"/>\n</Relationships>`\n\n  const workbook = `<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>\n<workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"\n xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\">\n<sheets><sheet name=\"报销单\" sheetId=\"1\" r:id=\"rId1\"/></sheets></workbook>`\n\n  const workbookRels = `<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>\n<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">\n<Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet1.xml\"/>\n<Relationship Id=\"rId2\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles\" Target=\"styles.xml\"/>\n</Relationships>`\n\n  const styles = `<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>\n<styleSheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\">\n<fonts count=\"1\"><font><sz val=\"11\"/><name val=\"Calibri\"/></font></fonts>\n<fills count=\"2\"><fill><patternFill patternType=\"none\"/></fill><fill><patternFill patternType=\"gray125\"/></fill></fills>\n<borders count=\"1\"><border><left/><right/><top/><bottom/><diagonal/></border></borders>\n<cellStyleXfs count=\"1\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\"/></cellStyleXfs>\n<cellXfs count=\"1\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\" xfId=\"0\"/></cellXfs>\n</styleSheet>`\n\n  const core = `<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>\n<cp:coreProperties xmlns:cp=\"http://schemas.openxmlformats.org/package/2006/metadata/core-properties\" xmlns:dc=\"http://purl.org/dc/elements/1.1/\" xmlns:dcterms=\"http://purl.org/dc/terms/\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\">\n<dc:creator>dsh-invoice-tools</dc:creator>\n<cp:lastModifiedBy>dsh-invoice-tools</cp:lastModifiedBy>\n<dcterms:created xsi:type=\"dcterms:W3CDTF\">${new Date().toISOString()}</dcterms:created>\n<dcterms:modified xsi:type=\"dcterms:W3CDTF\">${new Date().toISOString()}</dcterms:modified>\n</cp:coreProperties>`\n\n  const app = `<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>\n<Properties xmlns=\"http://schemas.openxmlformats.org/officeDocument/2006/extended-properties\" xmlns:vt=\"http://schemas.openxmlformats.org/officeDocument/2006/docPropsVTypes\">\n<Application>dsh-invoice-tools</Application></Properties>`\n\n  return buildZip([\n    { name: '[Content_Types].xml', data: textEncode(contentTypes) },\n    { name: '_rels/.rels', data: textEncode(rels) },\n    { name: 'docProps/core.xml', data: textEncode(core) },\n    { name: 'docProps/app.xml', data: textEncode(app) },\n    { name: 'xl/workbook.xml', data: textEncode(workbook) },\n    { name: 'xl/_rels/workbook.xml.rels', data: textEncode(workbookRels) },\n    { name: 'xl/styles.xml', data: textEncode(styles) },\n    { name: 'xl/worksheets/sheet1.xml', data: textEncode(sheet) },\n  ])\n}\n\n/** 默认报销单基础文件名（不含扩展名）。 */\nexport function reimbursementBaseName(date?: Date): string {\n  const d = date ?? new Date()\n  const y = d.getFullYear()\n  const m = String(d.getMonth() + 1).padStart(2, '0')\n  const day = String(d.getDate()).padStart(2, '0')\n  return `报销单-${y}${m}${day}`\n}"
