      "path": "tests/smoke.e2e.ts",
      "content": "/**\n * tests/smoke.e2e.ts — dsh-invoice-tools 离线冒烟测试（fixture 内嵌）。\n *\n * 运行：node --test tests/smoke.e2e.ts（Node ≥ 22.19 原生执行 .ts，无需 npm install）\n * 或：npm run test:offline\n *\n * fixture 全部内嵌生成（自写最小 PDF 生成器），覆盖验收标准 1-5：\n *   ① 含 XML 附件的样例解析字段完整 + 勾稽通过 + confidence=high；\n *   ② 无 XML 的文本型样例走正则路径 + confidence=medium；\n *   ③ 3 张样例汇总：合计正确 + 重复检测命中构造样本；\n *   ④ xlsx 输出：ZIP 结构 + 表头/行数据断言；openpyxl 交叉验证在环境可用时执行，\n *      缺失时显式打印 `-- SKIP openpyxl 交叉验证（python3/openpyxl 缺失）` 并计入\n *      skipped（node:test skip 语义，不再静默跳过）；\n *   ⑤ 异常文件（加密 PDF / 纯图片）返回明确跳过判定，不中断批量；\n *   ⑥ 勾稽不符样本标红（check fail）。\n */\n\nimport { test } from 'node:test'\nimport assert from 'node:assert/strict'\nimport { mkdtempSync, writeFileSync, rmSync } from 'node:fs'\nimport { tmpdir } from 'node:os'\nimport { join } from 'node:path'\nimport { inflateRawSync } from 'node:zlib'\nimport { spawnSync } from 'node:child_process'\n\nimport {\n  collectXmlTags,\n  fieldsFromXmlTags,\n  normalizeMoney,\n  normalizeDate,\n  parseInvoiceFromTextLines,\n  parseInvoiceFromXml,\n  validateInvoice,\n  type InvoiceData,\n} from '../src/invoice-model.ts'\nimport { extractPdf, detectFileKind } from '../src/pdf-extract.ts'\nimport { summarizeInvoices, renderMarkdown, renderXlsx, buildZip, reimbursementBaseName } from '../src/summary.ts'\n\n// ---------------------------------------------------------------------------\n// fixture：自写最小 PDF 生成器（传统 xref 表；文本层 UTF-16BE hex；XML 附件未压缩）\n// ---------------------------------------------------------------------------\n\n/** 字符串 → UTF-16BE hex（带 FEFF BOM），用于文本层 hex string。 */\nfunction utf16Hex(s: string): string {\n  let out = 'FEFF'\n  for (const ch of s) {\n    const cp = ch.codePointAt(0)!\n    if (cp > 0xffff) {\n      const hi = 0xd800 + ((cp - 0x10000) >> 10)\n      const lo = 0xdc00 + ((cp - 0x10000) & 0x3ff)\n      out += hi.toString(16).padStart(4, '0') + lo.toString(16).padStart(4, '0')\n    } else out += cp.toString(16).padStart(4, '0')\n  }\n  return out\n}\n\nfunction textEncode(s: string): Uint8Array {\n  return new TextEncoder().encode(s)\n}\n\n/** 文本层 Content 流：每行 <FEFF...> Tj 0 -14 Td。 */\nfunction contentStream(lines: string[]): string {\n  if (lines.length === 0) return ''\n  const ops = lines.map((l, i) => (i === 0 ? `<${utf16Hex(l)}> Tj` : `0 -14 Td <${utf16Hex(l)}> Tj`)).join(' ')\n  return `BT /F1 12 Tf 72 720 Td ${ops} ET`\n}\n\ninterface PdfFixtureOpts {\n  textLines?: string[]\n  xml?: string\n  encrypt?: boolean\n  /** 注入额外对象（原始文本段），用于覆盖特殊形态。 */\n  catalogExtra?: string\n}\n\n/** 生成传统 xref 表结构的最小 PDF。 */\nfunction buildPdf(opts: PdfFixtureOpts): Uint8Array {\n  const parts: Uint8Array[] = []\n  const offsets = new Map<number, number>()\n  let cursor = 0\n  const push = (bytes: Uint8Array) => {\n    parts.push(bytes)\n    cursor += bytes.length\n  }\n  const reg = (n: number, body: string) => {\n    offsets.set(n, cursor)\n    push(textEncode(`${n} 0 obj\\n${body}\\nendobj\\n`))\n  }\n\n  push(textEncode('%PDF-1.4\\n'))\n  const xml = opts.xml\n  const content = contentStream(opts.textLines ?? [])\n  const contentBytes = textEncode(content)\n\n  const namesEntry = xml ? ` /Names << /EmbeddedFiles << /Names [(Invoice.xml) 6 0 R] >> >> ` : ' '\n  reg(1, `<< /Type /Catalog /Pages 2 0 R${opts.encrypt ? ' /Encrypt 8 0 R' : ''}${opts.catalogExtra ?? ''}${namesEntry}>>`)\n  reg(2, '<< /Type /Pages /Kids [3 0 R] /Count 1 >>')\n  reg(3, '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Contents 4 0 R /Resources << >> >>')\n  reg(4, `<< /Length ${contentBytes.length} >>\\nstream\\n${content}\\nendstream`)\n\n  if (xml) {\n    reg(6, '<< /Type /Filespec /F (Invoice.xml) /UF (Invoice.xml) /Desc (Invoice XML) /EF << /F 7 0 R >> >>')\n    const xmlBytes = textEncode(xml)\n    reg(7, `<< /Type /EmbeddedFile /Subtype /XML /Length ${xmlBytes.length} >>\\nstream\\n${xml}\\nendstream`)\n  }\n  if (opts.encrypt) {\n    reg(8, '<< /Filter /Standard /V 2 /R 3 /O (xxxxxxxxxxxxxxxx) /U (yyyyyyyyyyyyyyyy) /P -1 >>')\n  }\n\n  const maxNum = Math.max(...offsets.keys(), 1)\n  const xrefOffset = cursor\n  push(textEncode(`xref\\n0 ${maxNum + 1}\\n0000000000 65535 f \\n`))\n  for (let i = 1; i <= maxNum; i++) {\n    const off = offsets.get(i) ?? 0\n    push(textEncode(`${String(off).padStart(10, '0')} 00000 n \\n`))\n  }\n  push(textEncode(`trailer\\n<< /Size ${maxNum + 1} /Root 1 0 R >>\\nstartxref\\n${xrefOffset}\\n%%EOF`))\n\n  const total = cursor\n  const out = new Uint8Array(total)\n  let w = 0\n  for (const p of parts) {\n    out.set(p, w)\n    w += p.length\n  }\n  return out\n}\n\n// ---------------------------------------------------------------------------\n// 样例数据\n// ---------------------------------------------------------------------------\n\nconst XML_A = `<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<Invoice>\n  <InvoiceCode>044001900111</InvoiceCode>\n  <InvoiceNo>24412000000012345678</InvoiceNo>\n  <IssueDate>2024-01-05</IssueDate>\n  <TaxExclusiveAmount>100.00</TaxExclusiveAmount>\n  <TaxAmount>13.00</TaxAmount>\n  <TaxInclusiveAmount>113.00</TaxInclusiveAmount>\n  <BuyerName>北京示例科技有限公司</BuyerName>\n  <BuyerTaxId>91110108MA01ABCDEF</BuyerTaxId>\n  <SellerName>上海示例贸易有限公司</SellerName>\n  <SellerTaxId>91310115MA1K123456</SellerTaxId>\n  <VerifyUrl>https://inv-veri.chinatax.gov.cn/</VerifyUrl>\n</Invoice>`\n\nconst XML_B = XML_A\n  .replace('044001900111', '044002200222')\n  .replace('24412000000012345678', '24412000000087654321')\n  .replace('2024-01-05', '2024-02-10')\n  .replace('100.00', '200.00')\n  .replace('13.00', '26.00')\n  .replace('113.00', '226.00')\n  .replace('北京示例科技有限公司', '北京示例科技有限公司')\n  .replace('上海示例贸易有限公司', '上海示例实业有限公司')\n\n/** 文本型样本 C（无 XML，走正则路径）：金额 50.00 / 税额 3.00 / 合计 53.00。 */\nconst TEXT_C = [\n  '发票号码：98765432101234567890',\n  '开票日期：2024年03月15日',\n  '购买方名称：深圳示例科技有限公司',\n  '购买方纳税人识别号：91440300MA5ABCDEFG',\n  '销售方名称：广州示例服务有限公司',\n  '销售方纳税人识别号：91440101MA5GHIJKLM',\n  '金额（小写）¥50.00',\n  '税额（小写）¥3.00',\n  '价税合计（大写）伍拾叁圆整（小写）¥53.00',\n  '查验平台：https://inv-veri.chinatax.gov.cn/',\n]\n\n// ---------------------------------------------------------------------------\n// 测试\n// ---------------------------------------------------------------------------\n\ntest('① XML 附件解析字段完整、勾稽通过、confidence=high', () => {\n  const pdf = buildPdf({ textLines: TEXT_C, xml: XML_A })\n  const extraction = extractPdf(pdf)\n  assert.equal(extraction.encrypted, false)\n  assert.ok(extraction.embeddedXml.length >= 1, '应提取到 XML 附件')\n  assert.ok(extraction.embeddedXml[0].includes('InvoiceNo'))\n  assert.ok(extraction.text.includes('发票号码'), '文本层应包含发票号码行')\n\n  const inv = parseInvoiceFromXml(extraction.embeddedXml[0], 'A.pdf', extraction.text)\n  assert.equal(inv.invoiceNumber, '24412000000012345678')\n  assert.equal(inv.invoiceCode, '044001900111')\n  assert.equal(inv.amount, 100)\n  assert.equal(inv.tax, 13)\n  assert.equal(inv.total, 113)\n  assert.equal(inv.issueDate, '2024-01-05')\n  assert.equal(inv.buyer.name, '北京示例科技有限公司')\n  assert.equal(inv.buyer.taxId, '91110108MA01ABCDEF')\n  assert.equal(inv.seller.name, '上海示例贸易有限公司')\n  assert.equal(inv.seller.taxId, '91310115MA1K123456')\n  assert.equal(inv.verifyUrl, 'https://inv-veri.chinatax.gov.cn/')\n  assert.equal(inv.source.method, 'xml')\n  assert.equal(inv.source.confidence, 'high')\n  assert.deepEqual(inv.source.missing, [])\n\n  const checks = validateInvoice(inv)\n  const recon = checks.find((c) => c.label.startsWith('勾稽'))!\n  assert.equal(recon.ok, true, '勾稽应通过')\n\n  // 第二张（B）\n  const pdfB = buildPdf({ xml: XML_B, textLines: [] })\n  const extractedB = extractPdf(pdfB)\n  const invB = parseInvoiceFromXml(extractedB.embeddedXml[0], 'B.pdf', extractedB.text)\n  assert.equal(invB.total, 226)\n  assert.equal(invB.tax, 26)\n  assert.equal(invB.source.confidence, 'high')\n})\n\ntest('② 无 XML 文本型样例走正则路径、confidence=medium', () => {\n  const pdf = buildPdf({ textLines: TEXT_C }) // 无 xml\n  const extraction = extractPdf(pdf)\n  assert.equal(extraction.embeddedXml.length, 0)\n  assert.ok(extraction.text.length > 0)\n\n  const inv = parseInvoiceFromTextLines(extraction.text, 'C.pdf')\n  assert.equal(inv.invoiceNumber, '98765432101234567890')\n  assert.equal(inv.amount, 50)\n  assert.equal(inv.tax, 3)\n  assert.equal(inv.total, 53)\n  assert.equal(inv.issueDate, '2024-03-15')\n  assert.equal(inv.buyer.name, '深圳示例科技有限公司')\n  assert.equal(inv.buyer.taxId, '91440300MA5ABCDEFG')\n  assert.equal(inv.seller.name, '广州示例服务有限公司')\n  assert.equal(inv.seller.taxId, '91440101MA5GHIJKLM')\n  assert.equal(inv.source.method, 'regex')\n  assert.equal(inv.source.confidence, 'medium')\n  // 全电发票无发票代码属正常缺失（次要字段，不拉低置信度）；关键字段无缺失\n  assert.deepEqual(inv.source.missing, ['发票代码'])\n  assert.ok(!inv.source.missing.some((m) => ['发票号码', '金额', '税额', '价税合计'].includes(m)))\n  assert.equal(validateInvoice(inv).find((c) => c.label.startsWith('勾稽'))!.ok, true)\n})\n\ntest('②b 文本正则：金额/税额 与 价税合计 标签后缀碰撞修复（含价税合计断言）', () => {\n  // 版式 1：精确标签\"金额（不含税）\"与\"价税合计\"分开取数，勾稽通过\n  const linesExact = [\n    '发票号码：77777777777777777777',\n    '开票日期：2024年05月06日',\n    '金额（不含税）¥100.00',\n    '税额（小写）¥13.00',\n    '价税合计（大写）壹佰壹拾叁元整（小写）¥113.00',\n  ]\n  const invExact = parseInvoiceFromTextLines(linesExact.join('\\n'), 'A-exact.pdf')\n  assert.equal(invExact.amount, 100)\n  assert.equal(invExact.tax, 13)\n  assert.equal(invExact.total, 113)\n  assert.equal(validateInvoice(invExact).find((c) => c.label.startsWith('勾稽'))!.ok, true)\n\n  // 版式 2（审计实测碰撞版式）：合计金额行携带的是价税合计数值 113.00，\n  // \"金额\"标签不得命中\"合计金额\"把价税合计误当金额/税额\n  const linesCollision = [\n    '发票号码：88888888888888888888',\n    '开票日期：2024年06月07日',\n    '合计金额（大写）壹佰元整（小写）¥113.00',\n    '合计税额（大写）壹拾叁元整（小写）¥13.00',\n    '价税合计（大写）壹佰壹拾叁元整（小写）¥113.00',\n  ]\n  const invB = parseInvoiceFromTextLines(linesCollision.join('\\n'), 'B-collision.pdf')\n  assert.equal(invB.total, 113, '价税合计应取到 113.00')\n  assert.notEqual(invB.amount, 113, '金额不得误取价税合计数值（合计金额前缀应被排除）')\n  assert.notEqual(invB.tax, 113, '税额不得误取价税合计数值')\n  assert.equal(invB.amount, 0)\n  assert.equal(invB.tax, 0)\n  assert.equal(invB.source.confidence, 'low', '合计行不绑定金额/税额 → 关键字段缺失降级 low')\n  assert.ok(invB.source.missing.includes('金额') && invB.source.missing.includes('税额'))\n\n  // 版式 3：精确标签在\"合计金额（携带价税合计值）\"之前出现时，取第一个合法标签行\n  const linesMixed = [\n    '发票号码：66666666666666666666',\n    '金额（不含税）¥100.00',\n    '税额（小写）¥13.00',\n    '合计金额（大写）壹佰元整（小写）¥113.00',\n    '价税合计（大写）壹佰壹拾叁元整（小写）¥113.00',\n  ]\n  const invC = parseInvoiceFromTextLines(linesMixed.join('\\n'), 'C-mixed.pdf')\n  assert.equal(invC.amount, 100, '金额应从\"金额（不含税）\"行取 100.00 而非合计行 113.00')\n  assert.equal(invC.tax, 13)\n  assert.equal(invC.total, 113)\n  assert.equal(validateInvoice(invC).find((c) => c.label.startsWith('勾稽'))!.ok, true)\n})\n\ntest('③ 汇总 3 张样例：合计正确 + 重复检测命中构造样本', () => {\n  const mk = (file: string, no: string, amount: number, tax: number, total: number): InvoiceData => {\n    const inv: InvoiceData = {\n      invoiceCode: '044001900111',\n      invoiceNumber: no,\n      amount,\n      tax,\n      total,\n      issueDate: '2024-01-05',\n      buyer: { name: '甲方', taxId: 'T1' },\n      seller: { name: '乙方', taxId: 'T2' },\n      checks: [],\n      source: { file, method: 'xml', confidence: 'high', missing: [] },\n    }\n    inv.checks = validateInvoice(inv)\n    return inv\n  }\n  const A = mk('A.pdf', '24412000000012345678', 100, 13, 113)\n  const B = mk('B.pdf', '24412000000087654321', 200, 26, 226)\n  const C = mk('C.pdf', '98765432101234567890', 50, 3, 53)\n  const D = mk('D.pdf', '98765432101234567890', 50, 3, 53) // 与 C 同票号同金额 → 重复\n\n  const summary = summarizeInvoices([A, B, C, D])\n  assert.equal(summary.totals.count, 4)\n  assert.equal(summary.totals.amount, 400)\n  assert.equal(summary.totals.tax, 45)\n  assert.equal(summary.totals.total, 445)\n\n  // 重复检测\n  assert.equal(summary.duplicates.length, 1)\n  const dup = summary.duplicates[0]\n  assert.equal(dup.invoiceNumber, '98765432101234567890')\n  assert.equal(dup.amount, 50)\n  assert.deepEqual(dup.flagged, ['D.pdf'])\n\n  // 分类小计（默认未分类）\n  assert.equal(summary.byCategory.length, 1)\n  assert.equal(summary.byCategory[0].category, '未分类')\n  assert.equal(summary.byCategory[0].total, 445)\n\n  // 类别覆盖后\n  const withCat = summarizeInvoices([A, C])\n  // 直接构造带类别\n  const A2 = { ...A, category: '差旅' }\n  const C2 = { ...C, category: '办公' }\n  const s2 = summarizeInvoices([A2, C2])\n  assert.deepEqual(s2.byCategory.map((c) => [c.category, c.total]), [['差旅', 113], ['办公', 53]])\n})\n\ntest('④ xlsx 输出：ZIP 结构 + 表头与行数据断言（openpyxl 交叉验证可选）', async (t) => {\n  const mk = (file: string, no: string, amount: number, tax: number, total: number): InvoiceData => ({\n    invoiceCode: '044001900111',\n    invoiceNumber: no,\n    amount,\n    tax,\n    total,\n    issueDate: '2024-01-05',\n    buyer: { name: '甲方', taxId: 'T1' },\n    seller: { name: '乙方', taxId: 'T2' },\n    checks: [],\n    source: { file, method: 'xml', confidence: 'high', missing: [] },\n  })\n  const invoices = [\n    mk('A.pdf', '24412000000012345678', 100, 13, 113),\n    mk('B.pdf', '24412000000087654321', 200, 26, 226),\n    mk('C.pdf', '98765432101234567890', 50, 3, 53),\n  ]\n  const summary = summarizeInvoices(invoices)\n  const bytes = renderXlsx(invoices, summary)\n\n  // ZIP 魔数\n  assert.equal(bytes[0], 0x50)\n  assert.equal(bytes[1], 0x4b)\n  assert.equal(bytes[2], 0x03)\n  assert.equal(bytes[3], 0x04)\n\n  // 解包\n  const entries = unzip(bytes)\n  assert.ok(entries.has('[Content_Types].xml'))\n  assert.ok(entries.has('xl/workbook.xml'))\n  assert.ok(entries.has('xl/worksheets/sheet1.xml'))\n  const sheet = new TextDecoder().decode(entries.get('xl/worksheets/sheet1.xml')!)\n  assert.ok(sheet.includes('发票号码'), '表头应包含发票号码')\n  assert.ok(sheet.includes('价税合计'), '表头应包含价税合计')\n  assert.ok(sheet.includes('<v>113.00</v>'), '行数据应包含 A 张价税合计 113.00')\n  assert.ok(sheet.includes('<v>392.00</v>'), '合计行应包含 392.00')\n  assert.ok(sheet.includes('合计'), '合计行存在')\n\n  // 写盘交叉验证：openpyxl 可用时执行第三方断言；缺失时显式标记并计入 skipped\n  // （node:test skip 语义，不再静默跳过）\n  const dir = mkdtempSync(join(tmpdir(), 'dsh-invoice-'))\n  const xlsxPath = join(dir, '报销单-test.xlsx')\n  writeFileSync(xlsxPath, bytes)\n  try {\n    const probe = spawnSync('python3', ['-c', 'import openpyxl; print(\"ok\")'], { encoding: 'utf8' })\n    const openpyxlAvailable = probe.status === 0\n    await t.test('openpyxl 交叉验证', {\n      skip: openpyxlAvailable ? false : '-- SKIP openpyxl 交叉验证（python3/openpyxl 缺失）',\n    }, () => {\n      const py = spawnSync('python3', [\n        '-c',\n        'import openpyxl,sys; wb=openpyxl.load_workbook(sys.argv[1]); ws=wb[\"报销单\"]; assert ws.cell(1,1).value==\"#\"; assert ws.cell(1,2).value==\"发票号码\"; assert ws.max_row==5, ws.max_row; assert abs(ws.cell(5,7).value-392.0)<1e-6, ws.cell(5,7).value; print(\"rows\", ws.max_row)',\n        xlsxPath,\n      ], { encoding: 'utf8' })\n      assert.equal(py.status, 0, `openpyxl 交叉验证失败: ${py.stderr}`)\n      assert.match(py.stdout, /rows 5/)\n    })\n  } finally {\n    rmSync(dir, { recursive: true, force: true })\n  }\n})\n\ntest('⑤ 异常文件：加密 PDF / 纯图片 判定明确且不中断', () => {\n  // 加密 PDF\n  const encryptedPdf = buildPdf({ textLines: TEXT_C, xml: XML_A, encrypt: true })\n  const ex = extractPdf(encryptedPdf)\n  assert.equal(ex.encrypted, true, '应检测到 /Encrypt')\n\n  // 纯图片（PNG 头）\n  const png = new Uint8Array([137, 80, 78, 71, 13, 10, 26, 10, 0, 1, 2, 3])\n  assert.equal(detectFileKind(png, 'scan.png'), 'png')\n  const jpg = new Uint8Array([0xff, 0xd8, 0xff, 0xe0, 0, 0])\n  assert.equal(detectFileKind(jpg, 'scan.jpg'), 'jpg')\n  const pdfBytes = buildPdf({ textLines: TEXT_C })\n  assert.equal(detectFileKind(pdfBytes, 'invoice.pdf'), 'pdf')\n  assert.equal(detectFileKind(new Uint8Array([1, 2, 3]), 'weird.bin'), 'other')\n\n  // 无文本层且无 XML 的 PDF → text/xml 均为空（工具层判定 empty-pdf 跳过）\n  const emptyPdf = buildPdf({ textLines: [] })\n  const ex2 = extractPdf(emptyPdf)\n  assert.equal(ex2.text, '')\n  assert.equal(ex2.embeddedXml.length, 0)\n})\n\ntest('⑥ 勾稽不符样本标红（check fail）', () => {\n  const badXml = XML_A.replace('<TaxInclusiveAmount>113.00</TaxInclusiveAmount>', '<TaxInclusiveAmount>113.01</TaxInclusiveAmount>')\n  const pdf = buildPdf({ xml: badXml })\n  const ex = extractPdf(pdf)\n  const inv = parseInvoiceFromXml(ex.embeddedXml[0], 'bad.pdf', ex.text)\n  const checks = validateInvoice(inv)\n  const recon = checks.find((c) => c.label.startsWith('勾稽'))!\n  assert.equal(recon.ok, false)\n  assert.match(recon.detail ?? '', /113\\.01/)\n})\n\ntest('mixed 路径：XML 缺字段时文本层补齐 → method=mixed', () => {\n  // XML 金额/税额 50/3（与文本层一致），但缺价税合计标签 → 由文本层补齐 total=53\n  const xmlNoTotal = XML_A\n    .replace('<TaxExclusiveAmount>100.00</TaxExclusiveAmount>', '<TaxExclusiveAmount>50.00</TaxExclusiveAmount>')\n    .replace('<TaxAmount>13.00</TaxAmount>', '<TaxAmount>3.00</TaxAmount>')\n    .replace('<TaxInclusiveAmount>113.00</TaxInclusiveAmount>', '')\n  const pdf = buildPdf({ xml: xmlNoTotal, textLines: TEXT_C })\n  const ex = extractPdf(pdf)\n  const inv = parseInvoiceFromXml(ex.embeddedXml[0], 'mix.pdf', ex.text)\n  assert.equal(inv.total, 53, 'total 应来自文本层补齐')\n  assert.equal(inv.amount, 50)\n  assert.equal(inv.tax, 3)\n  assert.equal(inv.source.method, 'mixed')\n  assert.equal(inv.source.confidence, 'high')\n  assert.equal(validateInvoice(inv).find((c) => c.label.startsWith('勾稽'))!.ok, true)\n})\n\ntest('中文标签 XML（fieldsFromXmlTags）', () => {\n  const zhXml = `<?xml version=\"1.0\"?>\n<Invoice>\n  <发票代码>044001900111</发票代码>\n  <发票号码>24412000000012345678</发票号码>\n  <开票日期>2024-01-05</开票日期>\n  <金额>100.00</金额>\n  <税额>13.00</税额>\n  <价税合计>113.00</价税合计>\n  <购买方名称>中文购买方</购买方名称>\n  <销售方名称>中文销售方</销售方名称>\n</Invoice>`\n  const tags = collectXmlTags(zhXml)\n  const fields = fieldsFromXmlTags(tags)\n  assert.equal(fields.invoiceNumber, '24412000000012345678')\n  assert.equal(fields.amount, '100.00')\n  assert.equal(fields.total, '113.00')\n  assert.equal(fields.buyerName, '中文购买方')\n  assert.equal(fields.sellerName, '中文销售方')\n})\n\ntest('纯函数：金额/日期归一', () => {\n  assert.equal(normalizeMoney('¥1,234.56'), 1234.56)\n  assert.equal(normalizeMoney('￥100.00'), 100)\n  assert.equal(normalizeMoney('-50.00'), -50)\n  assert.equal(normalizeMoney('壹佰圆'), null)\n  assert.equal(normalizeDate('2024年01月05日'), '2024-01-05')\n  assert.equal(normalizeDate('20240105'), '2024-01-05')\n  assert.equal(normalizeDate('2024/1/5'), '2024-01-05')\n})\n\ntest('markdown 报销单渲染含表头与合计', () => {\n  const mk = (file: string, no: string, amount: number, tax: number, total: number): InvoiceData => ({\n    invoiceCode: '044001900111',\n    invoiceNumber: no,\n    amount,\n    tax,\n    total,\n    issueDate: '2024-01-05',\n    buyer: { name: '甲方', taxId: 'T1' },\n    seller: { name: '乙方', taxId: 'T2' },\n    checks: [],\n    source: { file, method: 'xml', confidence: 'high', missing: [] },\n  })\n  const list = [\n    mk('A.pdf', '24412000000012345678', 100, 13, 113),\n    mk('B.pdf', '24412000000087654321', 200, 26, 226),\n    mk('C.pdf', '98765432101234567890', 50, 3, 53),\n  ]\n  const s = summarizeInvoices(list)\n  const md = renderMarkdown(list, s, { generatedAt: '2026-08-23T00:00:00.000Z', title: '报销单' })\n  assert.ok(md.includes('| # | 发票号码 |'))\n  assert.ok(md.includes('**392.00**'))\n  assert.ok(md.includes('| **合计** |'))\n  assert.match(reimbursementBaseName(new Date(2026, 7, 23)), /^报销单-20260823$/)\n})\n\ntest('zip 打包器结构完整（PK 头 + EOCD）', () => {\n  const zip = buildZip([{ name: 'a.txt', data: textEncode('hello') }])\n  assert.equal(zip[0], 0x50)\n  assert.equal(zip[1], 0x4b)\n  assert.equal(zip[2], 0x03)\n  assert.equal(zip[3], 0x04)\n  const tail = zip.subarray(zip.length - 22)\n  assert.equal(tail[0], 0x50)\n  assert.equal(tail[1], 0x4b)\n  assert.equal(tail[2], 0x05)\n  assert.equal(tail[3], 0x06)\n  const entries = unzip(zip)\n  assert.equal(new TextDecoder().decode(entries.get('a.txt')), 'hello')\n})\n\n// ---------------------------------------------------------------------------\n// 测试内最小 zip 读取器（只为断言，非交付代码）\n// ---------------------------------------------------------------------------\n\nfunction unzip(bytes: Uint8Array): Map<string, Uint8Array> {\n  const map = new Map<string, Uint8Array>()\n  let pos = 0\n  while (pos + 30 <= bytes.length) {\n    if (!(bytes[pos] === 0x50 && bytes[pos + 1] === 0x4b && bytes[pos + 2] === 0x03 && bytes[pos + 3] === 0x04)) break\n    const dv = new DataView(bytes.buffer, bytes.byteOffset + pos, 30)\n    const method = dv.getUint16(8, true)\n    const compSize = dv.getUint32(18, true)\n    const nameLen = dv.getUint16(26, true)\n    const extraLen = dv.getUint16(28, true)\n    const name = new TextDecoder().decode(bytes.subarray(pos + 30, pos + 30 + nameLen))\n    const data = bytes.subarray(pos + 30 + nameLen + extraLen, pos + 30 + nameLen + extraLen + compSize)\n    map.set(name, method === 8 ? inflateRawSync(data) : data)\n    pos = pos + 30 + nameLen + extraLen + compSize\n  }\n  return map\n}"
